programs.sol:
"""Approximate code-opening and corpus-metadata responses.

The main positive pulses are PHP's opening tag and an initial Python `def`.
Filename, star-count and issue-author markers produce negative pulses. A few
smaller rules cover tool boundaries, anonymized names and unusual whitespace.
Strengths are rounded training observations, not a complete lexical model.
The short suffix and comment count reset at each document boundary.
"""
READS = ()

DECLARATIONS = frozenset('''
class function let const var void struct namespace package import include using
'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, recent, comments, issue_record = 0, '', 0, False
    else:
        _, position, recent, comments, issue_record = carry
    text = recent + token
    value = -0.002
    if '\ufffd' in token:
        value = -0.018
    elif '\xa0' in token:
        value = -0.04 if len(token) == 1 else -0.10
    elif token == '\r':
        value = -0.12

    if position == 0:
        if token == 'def':
            value = 1.403
        elif token.strip() in DECLARATIONS:
            value = -0.44
        elif token == '<!':
            value = 3.95
        elif token == '<':
            value = -0.14
    if token == '<?':
        value = -0.30 if position == 0 else -0.01
    elif token == 'php' and recent.endswith('<?'):
        value = 1.034 if position == 1 else 0.19
    elif text.endswith('<filename'):
        value = -1.198 if position == 1 else -0.20
    elif text.endswith('<NAME'):
        value = -0.22
    elif token == '.lastname' and recent.endswith('firstname'):
        value = 0.44
    elif text.endswith('<gh'):
        value = -0.44
    elif text.endswith('<gh_stars'):
        value = -0.966 if position == 3 else -0.56
    elif text.endswith('<issue'):
        issue_record = issue_record or position == 1
        value = -0.214 if position == 1 else 0.05
        if position < 10 and '<issue_start>' in recent:
            value = 0.43
    elif token == '>' and recent.endswith('_comment'):
        value = -0.21
    elif token == ':' and recent.endswith('>Title') and position < 25:
        value = 0.28
    elif token == 'username' and (comments or issue_record):
        if recent.endswith(('>', '\n')):
            value = -0.40
            if comments == 1:
                value = -0.685 if issue_record else -0.50
    elif token == '_' and recent.endswith('username'):
        value = 0.10
    elif token == '<tool_call>':
        value = -0.11
    elif token == '<tool_response>':
        value = -0.068

    marker = '<issue_comment>'
    if marker in text and text.rfind(marker) + len(marker) > len(recent):
        comments += 1
    return (doc, position + 1, text[-128:], comments, issue_record), value

"""Detect backslash escapes locally; ordinary text receives almost zero.

A one-letter argument following a backslash is especially strong. Escapes
contained in one token are usually weaker. Newline punctuation and repeated
tab escapes distinguish code-layout contexts. An initial Title: header is
another, less frequent positive case. Frequent escape sequences are attenuated
as backslashes accumulate in a document. Constants summarize training examples.
"""
READS = ()

# Split control/encoding escapes and regular-expression character classes.
LETTERS = {'e': 4.5, 'x': 2.561, 'u': 1.9}
REGEX_CLASSES = frozenset('dDsSwW')
PUNCTUATION = {
    ',': 1.116, '|': 1.698, ';': 2.439, '*': -0.774,
    '!': -0.990, '%': -0.990, '$': 0.550, ' ': 0.721,
}
# When the slash and its argument are part of the same token.
WHOLE_ESCAPES = {
    'n': -0.045, 'r': 1.697, 'u': 0.737, 's': 1.692,
    'S': 1.692, 'a': 3.123, '.': 2.899,
}


def predict(s, p, age):
    if age == 1 and p == 'Title' and s == ':':
        return 10.0
    if age == 0 and s.startswith('\t'):
        return 1.341
    if p.endswith('\\'):
        double = p.endswith('\\\\')
        if s == 'n':
            before = p[:-1].rstrip()
            if double:
                return -0.060
            if before.endswith(('(', '{', '[', '^')):
                return 0.620
            if before.endswith(('.', '?')):
                return -0.160
            return 0.100
        if s in ('t', 'r'):
            return 0.307 if double else (1.174 if s == 't' else 1.980)
        if s == '0':  # null escape
            return 9.5
        if len(s) == 1 and s in '1234567':  # octal escape
            return 3.098
        if len(s) == 1 and s.isascii() and s.isalpha():
            return LETTERS.get(s, 2.814 if s in REGEX_CLASSES else 1.795)
        if s.startswith('\\"'):
            return -0.568
        q = s.rstrip('\\')
        if q and all(not ch.isalnum() for ch in q):
            # Two neighboring escapes can share the middle token.
            extra = 1.106 if q != s else 0.0
            if q.startswith('"'):
                return extra + (1.124 if ';' in q else 0.107)
            value = PUNCTUATION.get(q[0], 0.073)
            if q[0] in '()[]{}':
                value = 0.161
            if q[0] == '[':
                value = 1.614 if '"' in p else -0.095
            return value + extra
        if s.isalpha():
            if s[0].isupper() and len(s) > 1:
                return -0.176
            if len(s) <= 2:
                return 0.124
    if '\\' in s:
        left, _, right = s.partition('\\')
        if right.startswith('\n'):
            return 3.276  # a backslash followed by a physical newline
        if right == 't':
            return -0.020 if p == '\\t' else 0.765
        if right == 'x':
            return 2.019 if p in ('n', '\\n', '\n') else 0.622
        if right in WHOLE_ESCAPES:
            return WHOLE_ESCAPES[right]
        if right in ('[', '(', ')'):
            return 1.893 if right == '[' and p.endswith('"') else 0.252
        if right == '_':
            return -0.788 if p.isupper() else 0.676
        if right == '<':
            return -0.176
        if len(right) > 1 and right.isalpha() and right[0].isupper():
            return -0.973  # namespace-like names after a backslash
        if not right and left.rstrip().endswith(('.', ':', ';', ')')):
            return -0.221
    return 0.001


# Repetition dampens common escapes, with a larger novelty boost for tabs,
# hex escapes and a separately tokenized n than for a whole-token newline.
def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        p, age, count = '', 0, 0
    else:
        _, p, age, count = carry
    value = predict(s, p, age)
    common_escape = (s == 'n' and p.endswith('\\')) or s in ('\\n', '\\x')
    first_tab = s == '\\t' and p != '\\t'
    if common_escape or first_tab:
        gain = 0.5 if s == '\\n' else 0.75
        value += gain / (1 + count) ** 0.5 - 0.15
    return (doc, s, age + 1, count + s.count('\\')), float(value)

programs.haiku:
"""Layer 1 MLP down_proj component 1153: an escape-sequence / LaTeX-macro detector.

It is silent on most tokens. It fires on the token that completes a backslash escape
or a LaTeX macro (the single letter after a lone backslash, as in \\dagger, \\zeta,
\\text or \\x41), on backslash line continuations, and on a few escape-letter tokens
(\\t, \\x, \\[, |\\). It goes negative on PHP namespace backslashes (\\Models),
on markdown-escaped asterisks (*\\*) and on punctuation followed by an escaped newline.
It also spikes on the 'Title' ':' that opens a headline right after <|endoftext|>.
"""

READS = ()

# Escape-letter tokens: escape sequences that open a code or regex escape.
ESCAPE_TOKENS = {"\\t", "\\x", "\\[", "|\\", "\\.", "\\S"}
# Escaped newline after code punctuation, e.g. ");\n" written as text.
PUNCT_BEFORE_BS = (";\\", ":\\", ".\\", ")\\", "):\\", "');\\")


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    prev2 = prefix.token_strings[-3] if len(prefix) > 2 else ""

    if prev2 == "<|endoftext|>" and prev == "Title" and cur == ":":
        value = 10.0  # headline label opening a document
    elif "\\" in cur and cur.endswith("\n"):
        value = 3.1  # backslash line continuation
    elif prev.endswith("\\"):
        # the token right after a lone backslash
        if cur.isalpha() and len(cur) == 1:
            value = 0.1 if cur == "n" else 2.3  # \n is a plain newline escape
        elif cur.isalpha():
            value = 0.0
        elif prev == "*\\" and cur == "*":
            value = -1.5  # markdown-escaped asterisk
        else:
            value = 0.3
    elif cur in ESCAPE_TOKENS:
        value = 0.7
    elif cur.startswith("\\") and cur[1:2].isupper():
        value = -1.1  # PHP-style namespace separator
    elif cur.endswith("\\") and cur.endswith(PUNCT_BEFORE_BS):
        value = -0.2
    else:
        value = 0.0
    return None, value

programs.sol:
"""Approximate a Greek-letter and middle-dot response.

Greek prose is recognized by four Greek letters, including a three-letter
run, in the last 30 characters. Word starts give negative values (nu is
strongest), with smaller responses to internal nu/lambda combinations.
Space-prefixed incomplete Greek letters are recognized at their first byte.
Middle-dot runs and date separators give positive values; other middle
dots are weaker. Other tokens predict zero. State resets at documents.
"""
import codecs
import re
import unicodedata as ud

READS = ()
INITIAL = {
    'α': -3.5, 'β': -4.0, 'γ': -4.0, 'δ': -1.3,
    'ε': -1.1, 'κ': -3.8, 'λ': -4.8, 'μ': -3.1,
    'ν': -9.6, 'π': -1.3, 'σ': -2.8, 'τ': -0.95,
    'φ': -3.6, 'χ': -3.0, 'ω': -0.5,
}
MONTH = r'(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*'
DATE = re.compile(
    r'(?:\d{4}[-/]\d{1,2}[-/]\d{1,2}|'
    + MONTH + r'\s+\d{1,2},?\s+(?:\d{4})?)\s+$', re.I
)


def greek(ch):
    return 'GREEK' in ud.name(ch, '') and ch.isalpha()


def response(token, text, history, partial):
    s = text.strip()
    dots = bool(s) and set(s) == {'·'}
    letter = len(s) == 1 and greek(s)
    if not (dots or letter or token in (b' \xce', b' \xcf')):
        return 0.0
    recent = history[-30:]
    flags = ''.join('g' if greek(c) else '.' for c in recent)
    prose = flags.count('g') >= 4 and 'ggg' in flags
    if dots:
        if len(s) > 1:
            return 1.76
        date = DATE.search(history + text[:len(text)-len(text.lstrip())])
        if date:
            label = date.group().strip()
            if label[0].isdigit():
                return 12.8
            return 7.3 if len(label.split()[0]) == 3 else 1.5
        if prose:
            return 2.5
        return -0.4 if text.startswith(' ') else -0.1
    if not prose:
        return 0.0
    # These lead bytes begin Greek letters split across tokens.
    if token == b' \xcf':
        return -5.6
    if token == b' \xce':
        return -1.1
    if not letter:
        return 0.0
    base = ud.normalize('NFD', s)[0].lower()
    previous = history[-1:]
    initial = text[:1].isspace() or not history or not history[-1].isalpha()
    if initial:
        if s.isupper():
            if s in 'ΒΓΘΙΝ':
                return {'Β': -5.8, 'Γ': -4.5, 'Θ': -4.5,
                        'Ι': -3.0, 'Ν': -6.5}[s]
            return INITIAL.get(base, -1.0) * 0.8
        if partial:
            if s == 'ό':
                return -5.9
            if base == 'α':
                return -3.0
            if base in 'θχι':
                return -3.0
            if base == 'υ':
                return -1.8
            return -0.2
        return INITIAL.get(base, -1.2)
    if base == 'ν':
        p = ud.normalize('NFD', previous)[0] if previous else ''
        if p == 'ι':
            earlier = ud.normalize('NFD', history[-2:-1]).lower()
            return -0.8 if earlier in ('σ', 'τ', 'ρ') else -4.3
        if p in ('γ', 'χ', 'ν'):
            return -4.5
        return -0.8 if p == 'η' else -0.25
    if base == 'λ':
        p = ud.normalize('NFD', previous)[0] if previous else ''
        return -1.6 if p in ('λ', 'ι', 'η', 'κ') else -0.1
    if base == 'η':
        return -0.3
    return -0.05


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf-8')('ignore')
        history = ''
    else:
        _, decoder, history = carry
    partial = bool(decoder.getstate()[0])
    token = prefix.token_bytes[-1]
    text = decoder.decode(token)
    value = response(token, text, history, partial)
    return (doc, decoder, (history + text)[-80:]), value

"""Approximate a response to textual line labels and escape notation.

Line-number digits are negative, especially the first digit of repeated,
indented numbered lines. Patch-line signs are also negative. Most ordinary
text is close to zero. Doubled backslashes distinguish TeX line breaks from
escaped program text. Separator dots and document-initial "Title:"
metadata have separate responses. These are coarse formatting rules, not
a model of the smaller responses to ordinary words.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', False, '', 0)
    _, line, previous, patch, recent, position = carry
    s = prefix.token_strings[-1]
    value = -0.002
    number = re.fullmatch(r'([ \t]*)([0-9]*)', line)
    numbered = bool(re.match(r' *[0-9]+\t', previous))
    if len(s) == 1 and s in '0123456789':
        if number:
            indent, digits = number.groups()
            k = len(digits)
            if indent or numbered:
                strength = 1.0 if numbered else 0.35
                # Label strength falls rapidly across successive digits.
                alignment = 0.08 * (len(indent) == 3) * 0.8 ** k
                magnitude = 0.55 * 0.27 ** k
                magnitude += 0.23 * (k == 0 and s == '1')
                if s == '0':
                    magnitude *= 0.5
                value = -strength * (magnitude + alignment)
            elif k:
                value = 0.08
    patch = patch or bool(re.match(r'^[+-][ \t]{2,}', previous))
    if s.startswith(('+', '-')) and not line:
        if s == '+':
            value = -0.72 if patch else -0.4
            patch = True
        elif s == '+\n':
            value = -0.22 if patch else -0.08
            patch = True
        elif s.startswith(('---', '+++')):
            value = -0.03
        elif patch and s.startswith('-'):
            value = -0.9 if '\n' not in s else -0.2
    if '@@' in s or 'diff --git' in recent + s:
        patch = True
    if s == ':' and re.fullmatch(r' *[0-9]+', line):
        value = -0.2
    if s.startswith('\t') and number and number[2]:
        value = 0.06
    stripped = s.strip()
    if len(stripped) >= 2 and set(stripped) == {'\\'}:
        tex = s[0].isspace() or bool(re.search(
            r'\\(?:frac|sum|begin|left|right|mathbf|mathrm|pmatrix)\b',
            recent))
        if tex and len(stripped) == 2:
            value = 0.6
        else:
            n = len(stripped)
            value = -0.35 if n == 2 else -0.25 * min(8, n)
            if len(stripped) == 3:
                value = -0.5
    if len(stripped) >= 2 and set(stripped) == {'·'}:
        value = -0.43 * min(4, len(stripped))
    if position == 0 and s == 'Title':
        value = -1.34
    if position == 1 and line == 'Title' and s == ':':
        value = 2.73
    text = line + s
    if '\n' in text:
        parts = text.split('\n')
        previous, line = parts[-2][:96], parts[-1][:96]
    else:
        line = text[:96]
    recent = (recent + s)[-256:]
    return (doc, line, previous, patch, recent, position + 1), value

programs.haiku:
"""Numbers that start a line inside a numbered code listing.

Layer 1, MLP down-projection, component 1155 (layers.1.mlp.down_proj:1155).

The component writes a negative value when a number starts a line in a
line-numbered listing, such as the "  153" in "  153\tcode". Its response is
strongest on the first digit (about -0.3 on average), weaker on the second
digit (about -0.1) and weakest on the third (about -0.035). Digits in the
middle of a line, and numbers at the start of a line with no numbered lines
before them, give 0. Everything else gives 0.

The program reads only the tokens so far. For each digit it finds the start
of its number, checks that the number begins a line (only whitespace before
it on that line), and checks that an earlier line within the last 200 tokens
begins with a number (the listing context). It then returns the value for
the digit's position in the number.
"""

READS = ()

# Mean activation by position in the number: first, second, third digit.
DIGIT_VALUE = {0: -0.3, 1: -0.1, 2: -0.035}
LOOKBACK = 200  # tokens searched for an earlier numbered line


def _is_digit(token):
    return len(token) == 1 and token.isdigit()


def _starts_line(toks, i):
    """True if the tokens before index i, back to a newline, are only whitespace."""
    j = i - 1
    while j >= 0:
        if "\n" in toks[j]:
            return True
        if toks[j].strip():
            return False
        j -= 1
    return True  # start of the prefix counts as a line start


def _numbered_line_before(toks, start):
    """True if a line that ends before `start`, within LOOKBACK tokens, begins with a number."""
    for j in range(start - 1, max(0, start - LOOKBACK), -1):
        if "\n" in toks[j]:
            line = "".join(toks[j + 1 : start])
            if line.lstrip(" ")[:1].isdigit():
                return True
    return False


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = prefix.position
    if not _is_digit(toks[t]):
        return carry, 0.0
    # index of the first digit of this number, and this digit's position in it
    start = t
    while start - 1 >= 0 and _is_digit(toks[start - 1]):
        start -= 1
    position = t - start
    if not _starts_line(toks, start):
        return carry, 0.0
    if not _numbered_line_before(toks, start):
        return carry, 0.0
    return carry, DIGIT_VALUE.get(position, 0.0)

programs.sol:
"""Approximate negative responses to separated ASCII numbers and Latin letters.

Space-separated numerals respond most strongly, especially repeated or small
single digits. Single-letter notation has a similar, weaker response. Newlines,
wide gaps, commas and arithmetic signs modulate the response. A short numeric
history and document position adjust its strength. An initial digit instead
gets a small positive baseline. This recognizes formatting, not formula values.
"""
import re

READS = ()
WORD_END = re.compile(r'([A-Za-z]+|[0-9]+(?:\.[0-9]+)*)([^A-Za-z0-9]*)$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, age = '', 0
    else:
        _, tail, age = carry
    token = prefix.token_strings[-1]
    char = token.strip()
    digit = len(char) == 1 and char.isascii() and char.isdigit()
    letter = len(char) == 1 and char.isascii() and char.isalpha()
    value = 0.24 if age == 0 and digit else 0.0

    match = WORD_END.search(tail)
    if match:
        previous, gap = match.groups()
        gap += token[:len(token) - len(token.lstrip())]
        number = previous[0].isdigit()
        letters = previous.isalpha()
        single = len(previous) == 1
        spaced = bool(gap) and gap.isspace() and len(gap) < 12
        before = tail[:-len(match[0])]
        history = re.findall(r'[A-Za-z0-9]+', before)[-3:]
        recent_numbers = sum(word.isdigit() for word in history)
        early = 1 / (1 + age / 24)

        if digit and number:
            if spaced:
                value -= 0.72 + 0.06 * recent_numbers
                if single:
                    value -= 0.06 + 0.48 * (int(char) < 3)
                    value -= 0.21 * (int(previous) < 3)
                if '\n' in gap:
                    value += 0.52
                else:
                    value -= early * (0.49 + 1.65 * single)
                if len(gap) > 3:
                    value += 0.24
            elif gap in (',', ', '):
                value += 0.05
                if single:
                    value -= 0.17 + 0.07 * recent_numbers
                    value -= 0.15 * (char == previous)
            elif gap.strip() in ('+', '-', '*', '/', '×', '−'):
                value -= 0.05 + 0.07 * single
        elif digit and letters:
            if spaced and len(previous) <= 2:
                value -= 0.04 + 0.29 * previous.isupper()
        elif letter and number:
            if spaced:
                value -= 0.10
        elif letter and letters:
            # Primes mark modified letter symbols, not ordinary words.
            letter_gap = spaced or gap in ("' ", '′ ')
            if single and letter_gap:
                value -= 0.085 * early
                value -= 0.06 * (previous.islower() and char.islower())
                value -= 0.26 * (previous.isupper() and char.isupper())
                # English 'a' and 'I' need not be mathematical notation.
                value -= 0.20 * (previous not in ('a', 'I')
                                 and char not in ('a', 'I'))
                if not before or before.endswith('\n'):
                    value -= 0.31
            elif len(previous) == 2 and spaced and previous.isupper():
                value -= 0.13

        if (digit or letter) and spaced and char == previous:
            value -= 0.76
        if token.isspace():
            if '\n' not in token and number:
                value -= 0.03
            elif '\n' in token and letters and single:
                value -= 0.04

    return (doc, (tail + token)[-100:], age + 1), float(value)

"""Approximate an English activity-complement signal from a causal text tail.

The main negative triggers are verbs that take an activity ('continue',
'consider', 'enjoy', 'try') and prepositions. Their inflections differ in
strength. Noun uses and passive uses are weaker; activity-related nouns have
small positive values. Familiar complement phrases and auxiliary constructions
have fixed offsets, as in 'look forward to', 'end up', and 'there are'.
A code-fence flag and the text tail reset at document boundaries.
No future text is used; non-English lexical effects are left unexplained.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

# Verb families that allow a gerund/activity complement, with fitted strengths.
ACTIVITY_VERBS = (
    ('continue', 2.4),
    ('keep', 1.2),
    ('begin start resume', 1.25),
    ('try', 1.35),
    ('imagine contemplate envisage envision visualize', 1.65),
    ('consider reconsider', 1.3),
    ('enjoy recommend', 1.6),
    ('mention discuss anticipate recall remember', 1.05),
    ('avoid resist cease abandon', 1.0),
    ('quit', 2.1),
    ('finish stop', 0.8),
    ('appreciate hate dislike dread regret', 1.05),
    ('report suggest admit deny miss bother attempt', 0.6),
    ('spend', 0.5),
    ('love prefer', 0.65),
    ('describe explain emphasize request', 0.4),
    ('end complete', 0.15),
)
ROOT_VALUES = {w: v for words, v in ACTIVITY_VERBS for w in words.split()}
ACTIVITY_NOUNS = set('idea purpose approach practice intention proposal opinion'
                    ' question recommendation thought'
                    ' consideration chance regard'.split())
PREPOSITIONS = {
    'despite': -1.35, 'after': -0.48, 'before': -0.29,
    'upon': -0.29, 'into': -0.45, 'between': -0.29,
    'against': -0.25, 'from': -0.21, 'about': -0.08,
    'without': -0.12, 'to': -0.025, 'of': 0.0, 'up': 0.0,
}
MODALS = set('can could will would may might must should shall'.split())
SUBJECTS = set('i you he she it we they who'.split())
DETERMINERS = set('a an the this that my your his her its our their'.split())
BE = set('am is are was were be been being'.split())

# Familiar complement constructions: the preceding word is reduced to its
# dictionary base form. Negative phrases commonly admit an activity/gerund;
# positive ones tend instead to introduce a noun or an infinitive.
PHRASES = {
    'to': [('forward', -2.5), ('return switch resort commit', -1.1),
           ('addition prior back accustomed prone', -0.8),
           ('time chance opportunity ability', 0.4)],
