    'will would shall should may might must'
).split())
CLAUSE_VERBS = set((
    'know think believe suppose guess say report claim suggest assume '
    'ensure doubt hope feel'
).split())
CALENDAR = set((
    'day week month year night morning afternoon evening season century decade'
).split())
TIMEPOINTS = {'time', 'moment', 'second', 'minute', 'hour'}
DETERMINERS = {'this', 'that', 'last', 'next', 'every', 'each', 'previous', 'same'}
PRONOUNS = {'me', 'him', 'her', 'them', 'us', 'you', 'it', 'this', 'that'}
