    if w == 'there':
        if capital or not previous:
            return -0.8
        if not s.startswith(' '):
            return -1.9
        if p in SUBORDINATORS or p in {'maybe', 'perhaps', 'then', 'sure'}:
            return 0.25
        if p in COORDINATORS:
            return -0.8
        if punctuation:
