PUNCTUATION = {",", ".", "and", "but", "or", ":", ";", "!", "?", "(", ")", '"', "-", ""}
PREPOSITIONS = {"in", "on", "at", "from", "out", "back", "to", "for", "with", "by",
                "of", "around", "under", "over", "about", "into", "through", "near",
                "up", "down", "off", "across", "above", "below", "behind", "after",
                "before", "until", "like", "away", "than", "upon", "within", "during"}
VERBS_OF_BEING_OR_PLACE = {"is", "are", "was", "were", "be", "been", "being", "stood",
                           "lay", "sat", "stay", "stayed", "went", "drove", "go", "get",
                           "got", "came", "come", "live", "lived", "born", "stationed",
                           "left", "sitting", "standing", "can", "will", "would", "do"}
DEICTIC_ADVERBS = {"today", "tonight", "yesterday", "yet", "ago", "home", "online",
                   "earlier", "later", "nearby", "above", "below", "together", "back",
                   "again", "week", "year", "night", "morning"}
PRO_FORMS = {"it", "him", "them", "us", "me", "you", "her"}
