"""Recognize past-tense and completed-action forms, with a negative response.

English verb inflections come from WordNet. Regular -ed forms are strongest,
especially capitalized forms and endings split across tokens; ordinary
auxiliary/pronoun contexts soften the response. A few common grammatical
endings in other languages receive fixed negative responses. At a document's
first token, use a positive positional baseline instead of the morphology rule.
This is a morphological approximation, not a full tense or syntax parser.
"""
import re
from functools import lru_cache
import wordnet

