PAST_AUX = frozenset('was were had did been'.split())
AUXILIARIES = frozenset(
    'be am is are was were been being get got have has had'.split())
PRONOUNS = frozenset('i you he she it we they'.split())
ROMANCE_MASC_OR_PLURAL = frozenset('ado ados ido idos ato ati ito iti adas idas'.split())
ROMANCE_FEM_SINGULAR = frozenset('ada ida ata ita'.split())
JAPANESE_PAST = frozenset('た した った いた でした ました かった'.split())
RUSSIAN_PASSIVE = frozenset('ен ена ено ены енный ан анный нный анная анные'.split())


@lru_cache(maxsize=32768)
def morphology(word):
    """Inflection flag and -ed confidence: 2=dictionary, 1=guessed, 0=absent."""
    if word in {'am', 'are', 'is'} or word.endswith(('s', 'ing')):
        return False, 0
    bases = wordnet.base_forms(word, 'verb')
    changed = any(base != word for base in bases)
    regular = 0
    if word.endswith('ed') and word not in bases:
        stems = {word[:-2], word[:-1]}
        if word.endswith('ied'):
            stems.add(word[:-3] + 'y')
        if len(word) > 4 and word[-3] == word[-4]:
            stems.add(word[:-3])
