    text = prefix.token_strings[-1]
    match = re.search(r'[A-Za-z]+$', text)
    fragment = match.group().lower() if match else ''
    continuation = bool(fragment and match.start() == 0 and previous)
    word = ((previous if continuation else '') + fragment)[-64:]
    changed, regular = morphology(word)
    value = -0.006
    if regular:
        value -= 1.5 if regular == 2 else 0.5
        if continuation:
            value -= 0.6
        elif text[:1].isalpha():
            value -= 0.4
        if not match.group().islower():
            value -= 0.8
        recent = history.lower().split()[-3:]
        if any(w in AUXILIARIES for w in recent):
            value += 0.4
        if recent and recent[-1] in PRONOUNS:
            value += 0.8
    elif word in PAST_AUX:
        value -= 0.68
    elif changed:
        value -= 0.74
    elif word in SAME_PAST:
        value -= 0.17

    # Token-sized suffix pieces, not whole-word translations.
    if text == '了':
        value = -1.2
    elif text.endswith('了'):
        value = -0.5
    elif text in {'ée', 'ées', 'és'}:
        value = -1.1
    elif text == 'é':
        value = -0.4
    elif text in {'ó', 'ió', 'ò', 'ì'}:
        value = -0.8
    elif text in ROMANCE_MASC_OR_PLURAL:
        value = -0.9
    elif text in ROMANCE_FEM_SINGULAR:
        value = -0.4
    elif text in JAPANESE_PAST:
        value = -0.9
    elif text in RUSSIAN_PASSIVE:
        value = -0.3 if len(text) == 2 else -0.6
    if first:
        value = 0.65 if text[:1].isupper() else 0.45
    return (doc, word, (history + text)[-80:]), value

"""Quantity suffixes: measurement units, clock markers, rates and dimensions.

A bounded text buffer joins split unit words and remembers the quantity
before them. Units next to numbers are positive; ordinary prose is near zero.
There are also responses to 30/31 endings and repeated zeros in long numbers.
The final 0.8 factor conservatively calibrates these approximate rules.
"""
import re
from functools import lru_cache
import inflect
import wordnet

READS = ()
BASE = set('m g s A K N J W V C F H T S B L l M mol cd Hz Pa eV Ω'.split())
PREFIX = ('p', 'n', 'u', 'µ', 'μ', 'm', 'c', 'd', 'k', 'K', 'M', 'G', 'T')
SYMBOLS = BASE | {p + u for p in PREFIX for u in BASE}
SYMBOLS.update(('h hr yr min sec ft lb lbs oz mph rpm psi atm bar pc cc Å ° °C °F wt U k t p '
                'mi µ μ lm м см мм км кг мг Гц').split())
CJK_TIME = set('年 月 日 天 时 時 小时 小時 分 分钟 分鐘 秒'.split())
ASIAN = set(('米 千米 公里 厘米 毫米 公 升 毫 安 克 吨 噸 度 岁 歲 元 円 '
              '万 萬 億 亿 兆 平方').split())
SCALES = set('hundred thousand million billion trillion dozen lakh crore percent'.split())
STARTS = set('mic nan mill kil gig ang oh'.split())
CLOCK = set('AM PM am pm a.m. p.m. Uhr'.split())
DIMENSIONS = set('long wide high tall thick deep'.split())
_numbers = inflect.engine()
NUMBERS = {_numbers.number_to_words(n) for n in range(100)}
NUMBERS |= SCALES | set('half quarter once twice'.split())
WORD_PREFIXES = ('nano', 'micro', 'milli', 'centi', 'deci', 'kilo', 'mega', 'giga')


@lru_cache(maxsize=16384)
def kind(word):
    low = word.lower()
    if word in CLOCK:
        return 'clock'
    if word in SYMBOLS or (word.endswith('s') and word[:-1] in SYMBOLS):
        return 'symbol'
    if low in SCALES:
        return 'scale'
    if word in CJK_TIME:
        return 'time'
    if low in STARTS:
        return 'partial'
    if word in ASIAN or low in ('square', 'cubic', 'celsius', 'fahrenheit'):
        return 'unit'
    for prefix in WORD_PREFIXES:
        if low.startswith(prefix) and low != prefix and kind(low[len(prefix):]) == 'unit':
            return 'unit'
    if len(low) > 2:
        if 'noun.time' in wordnet.categories(low):
            return 'time'
        if wordnet.is_a(low, 'unit of measurement'):
            return 'unit'
    return 'other'


def number_before(text):
    words = text.strip().split()
    return bool(re.search(r'[零〇一二三四五六七八九十百千万亿兩两廿]+$',text) or
                re.search(r'(?:^|[^A-Za-z0-9_])\d+(?:[.,]\d+)*[ \t\xa0–-]*$', text) or
                (words and words[-1].lower() in NUMBERS))


def predict(tail, token):
    raw = token.strip()
    word = raw.lstrip('-').rstrip('.,;:()[]{}')
    # Rejoin alphabetic fragments, without joining unspaced Han sentences.
    m = re.search(r'[A-Za-zÀ-ÿµμ]+$', tail)
    joined = bool(m and re.match(r'[A-Za-zÀ-ÿµμ]', token))
    if joined:
        word = m.group() + word
    family = kind(word)
    adjacent = number_before(tail)
    digit_adjacent = bool(re.search(r'\d[ \t\xa0–-]*$', tail))
    recent = bool(re.search(r'\d[^\d\n]{0,18}$', tail))
    previous = re.search(r'([^\W\d_]+)[ \t\xa0-]*$', tail)
    after_unit = bool(previous and kind(previous.group(1)) != 'other' and
                      number_before(tail[:previous.start()]))

    if joined and family in ('unit', 'symbol', 'time'):
        after_unit |= number_before(tail[:m.start()])

    if token.isdecimal():
        if tail.endswith('3') and token in ('0', '1'):
            value = 1.05 if token == '0' else 0.65
            return value * (0.5 if len(tail) > 1 and tail[-2].isdigit() else 1)
        run = re.search(r'[\d.,]+$', tail)
        if token == '0' and tail.endswith('0') and run and len(run.group()) >= 4:
            return 0.65
        return 0.01
    if token.isspace():
        return (0.15 if '\xa0' in token else 0.03) if adjacent else 0.0
    if raw in ('℃', '℉') or (raw in ('C', 'F') and re.search(r'[°º˚◦•]\s*$', tail)):
        return 3.7 if recent else 0.0
    if raw in ('.m', 'm', '.m.') and re.search(r'[ap]\.m\.?$', tail + token, re.I):
        return 4.2 if recent else 0.0
    if '%' in raw or raw == '‰':
        return 0.7 if adjacent or recent else 0.0
    if raw in ('²', '³', '^2', '^3'):
        return 0.7 if after_unit else 0.0
    if family != 'other' and tail.endswith('/') and recent:
        return 2.5
    if raw.startswith('/') and kind(raw[1:]) != 'other':
        return 1.1 if after_unit else 0.5 if recent else 0.0
    if raw.lower().lstrip('-') in DIMENSIONS:
        measured = previous and number_before(tail[:previous.start()])
        lengths = ('m', 'km', 'cm', 'mm', 'ft')
        if measured and (len(previous.group(1)) > 2 or previous.group(1) in lengths):
            return 3.3
        return 2.7 if digit_adjacent else 0.0
    if word.lower() == 'time' and re.search(r'\bat a\s*$', tail, re.I):
        if re.search(r'\b(?:one|two|each|single)\b[^\n]{0,35} at a\s*$',tail,re.I):
            return 3.5
    if word.lower() == 'cent' and re.search(r'\bper\s*$', tail):
        return 3.5
    if family == 'time' and re.search(r'\b(?:per|a)\s*$', tail):
        if recent or any(w.lower() in NUMBERS for w in tail.split()[-7:]):
            return 3.0
    if word.lower() in ('per', 'each', 'every') and adjacent:
        return 1.4
    if family == 'clock' and raw not in CLOCK:
        return 0.0
    if family == 'clock':
        return (4.0 if token[:1].isspace() else 2.7) if adjacent else 0.0
    if family != 'other':
        strength = {'unit': 2.2, 'symbol': 1.9, 'partial': 2.3,
                    'time': 0.7, 'scale': 1.8}[family]
        if after_unit:
            if family == 'unit' and previous and previous.group(1) in ('square', 'cubic'):
                return 4.2
            if word in ASIAN:
                return 3.5
            if joined and family in ('unit', 'symbol'):
                return 3.0
            return strength
        if adjacent:
            if family == 'symbol' and len(raw) == 1:
                return 1.1 if token[:1].isspace() else 0.2
            if word not in SYMBOLS and word.endswith('s') and word[:-1] in SYMBOLS:
                return 3.0
            return strength * (1.0 if digit_adjacent else 0.55)
        return strength * 0.15 if recent else 0.0
    if adjacent and token[:1].isspace() and raw.isalpha():
        return 0.35 if 'noun' in wordnet.parts_of_speech(raw.lower()) else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (tail + token)[-100:]), 0.8 * float(predict(tail, token))

"""Predict negative pulses at date-format boundaries, especially padded months.

Two-digit months in YYYY-MM-DD and YYYY/MM/DD are the strongest ordinary
triggers. Smaller pulses mark digit boundaries, date endings and abbreviated
English months. Extra rules cover arrows, imports, metadata and middle dots.
All rules are causal; the short text buffer resets at document boundaries.
This approximates formatting responses, not the component's small lexical noise.
"""
import calendar
import re

READS = ()
SHORT_MONTHS = set(calendar.month_abbr[1:]) | {'Sept'}
MONTH = r'(?<![A-Za-z])(' + '|'.join(sorted(SHORT_MONTHS)) + r')'
MONTH_END = re.compile(MONTH + r'$')
MONTH_NUMBER = re.compile(MONTH + r' ([0-9]{1,2})$')
YEAR_MONTH = re.compile(r'([12][0-9]{3})([-/年])([0-9]{1,2})$')
DATE = re.compile(r'([12][0-9]{3})([-/年])([0-9]{1,2})[-/月]([0-9]{1,2})$')
PAIR = re.compile(r'(?<![0-9])([0-9]{1,2})([-/月])([0-9]{1,2})$')
NUMBER = re.compile(r'([0-9]+)$')
WEEKDAY = re.compile(r'(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun)\s+$')


def predict(prev, s):
    if s == '··':
        return -1.94
    if s.strip() in ('->', '→'):
        return -0.52 if s == ' ->' else -0.21
    if s.strip() == '{' and re.search(r'(?:\b|\\n)import(?: type)?$', prev):
        return -1.64
    if s == ':':
        if prev == '---\ntitle':
            return -30.96
        if prev.startswith('---\n') and prev.endswith('\ntitle'):
            return -12.0
        if prev == '---\nauthor':
            return -8.4
        if prev == 'Title':
            return -6.02
        if re.search(r'\bJoined$', prev):
            return -1.97
    if s == 'title' and prev == '---\n':
        return -4.10

    if s not in ('-', '/', '月', '日', ' ', 'T') and not (
            len(s) == 1 and s in '0123456789'):
        return 0.0

    ym = YEAR_MONTH.search(prev)
    date = DATE.search(prev)
    pair = PAIR.search(prev)
    named = MONTH_NUMBER.search(prev)
    if s in ('-', '/', '月', '日'):
        if ym and len(ym[3]) == 2 and 1 <= int(ym[3]) <= 12:
            if s == '月':
                return -3.8 if ym[3].startswith('0') else -1.0
            return {'-': -10.4, '/': -7.8}.get(s, 0.0)
        if pair and len(pair[3]) == 2:
            if s == '/' and pair[2] == '/':
                return -2.9 if int(pair[3]) <= 12 else -0.6
            if s == '日' and pair[2] == '月':
                return -0.6
            if s == '-' and pair[2] == '-':
                return -1.4 if int(pair[3]) <= 12 else -0.2
        n = NUMBER.search(prev)
        if n and len(n[1]) == 2 and 1 <= int(n[1]) <= 12:
            left = prev[:n.start()]
            if left.endswith('.'):
                return 0.0  # A decimal fraction, not a calendar field.
            line_start = not left.strip() or left.rstrip(' \t').endswith('\n')
            if s == '-' and n[1].startswith('0') and line_start:
                return -4.5
            if s == '/' and line_start:
                return -2.5 if n[1].startswith('0') else -1.8
            if n[1].startswith('0'):
                return -2.6 if s in ('/', '月') else -1.6
            return -0.8 if s == '/' else 0.1

    if len(s) == 1 and s in '0123456789':
        if date and len(date[3]) == 2 and int(date[3]) <= 12:
            if len(date[4]) == 1 and int(date[4] + s) <= 31:
                padded = date[4] == '0'
                if date[2] == '-':
                    return -4.2 if padded else -4.0
                if date[2] == '/':
                    return -1.8 if padded else -0.8
                return -1.2 if padded else -0.45
        if ym and len(ym[3]) == 1 and 1 <= int(ym[3] + s) <= 12:
            return -0.7 if ym[2] == '年' else -1.7
        if pair and len(pair[1]) == 2 and int(pair[1]) <= 12:
            if len(pair[3]) == 1:
                return -1.7 if pair[3] == '0' else -0.45
        if named and len(named[2]) == 1:
            before = prev[:named.start()]
            if named[2] == '0' or WEEKDAY.search(before):
                return -1.7
            if not re.search(r'[0-9]\s+$', before):
                return -0.35

    if s in (' ', 'T', '日') and date and len(date[4]) == 2:
        if len(date[3]) == 2 and int(date[3]) <= 12:
            return {' ': -1.5, 'T': -3.1, '日': -0.6}[s]
    if s == ' ':
        m = MONTH_END.search(prev)
        if m:
            before = prev[:m.start()]
            if WEEKDAY.search(before):
                return -4.2
            if not before.strip() or before.rstrip(' \t').endswith(('\n', '•')):
                return -2.6
            if re.search(
                    r'(?:Created on|Posted on|Commented|[Uu]pdated|[Ee]dited)[: ]*$',
                    before):
                return -2.5
            return -1.0
        if named and len(named[2]) == 2:
            return -0.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = predict(prev, s)
    return (doc, (prev + s)[-120:]), value

"""Approximate a local layout signal: alignment spaces versus block endings.

Multi-space tokens get positive values, reduced for ordinary code indentation.
Closing braces get more negative when the latest opener is distant or another
closer is nearby. Tabs and a few code/formatting markers have smaller rules.
This is not a brace-matching parser. It keeps 256 recent characters and the
position within the document; unhandled tokens get zero.

A word often owns one leading space, so blank-token widths 3, 7, 11, ...
commonly belong to four-column code indentation.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', '')
    _, position, tail, previous = carry
    token = prefix.token_strings[-1]
    stripped = token.strip()
    # Treat both real and escaped line endings as layout boundaries.
    text = tail.replace('\\n', '\n').replace('\\t', '\t')
    lines = text.split('\n')
    line = lines[-1]
    prior_line = lines[-2].rstrip() if len(lines) > 1 else ''
    line_start = not line.strip()
    indent = len(line) - len(line.lstrip(' \t'))
    opening = len(text) - text.rfind('{') if '{' in text else 10000
    closing = len(text) - text.rfind('}') if '}' in text else 10000
    code = any(c in text for c in '{};=')
    blank = previous.isspace()
    value = 0.0

    if len(token) > 1 and not token.strip(' '):
        width = len(token)
        if (width + 1) % 4 == 0:
            prose_end = prior_line[-1:].isalnum() or prior_line.endswith('.')
            value = 0.07 if code else (0.78 if prose_end else 0.32)
            if previous.strip().startswith('}'):
                value = -0.95 if position < 40 else -0.10
        elif blank:
            value = 0.75 if code else 1.12
        else:
            value = 0.68 if width == 2 else 0.24
        if line.strip().isdigit() and '\t' not in line and not code:
            value = 2.5

    elif token == ' ' and len(previous) > 1 and not previous.strip(' '):
        value = -0.30 if position < 40 else -0.035

    elif stripped.startswith('}') and not stripped[1:].strip(' \r\n\\n`'):
        if opening < 36:
            value = -0.52 if line_start else -0.05
        elif opening < 125:
            value = -1.53 if closing < 45 else -0.60
        elif position < 64:
            value = -4.29 if indent else -2.19
        else:
            value = -2.17 if closing < 17 else -1.23

    elif token and not token.strip('\t'):
        if position == 0:
            value = -3.16
        elif position < 6:
            value = -0.8
        elif position < 21:
            value = -0.30
        elif line_start:
            value = -0.32 if closing < 10 else 0.09
        else:
            value = -0.18

    elif stripped in ('return', 'return;'):
        if closing < 12:
            value = -1.81
        elif line_start or blank or token.startswith('\t'):
            value = -0.18 if opening < 32 else -0.85

    elif stripped in ('//', '/*', '#'):
        value = -0.77 if position < 2 else (-0.31 if closing < 12 else 0.0)

    elif stripped in ('public', 'private', 'protected', 'import', 'package'):
        value = -0.50 if '\t' in previous else (-0.23 if line_start else 0.0)

    elif stripped and not stripped.strip('`'):
        value = -0.63 if blank and not line_start else 0.0

    elif token == '<|endoftext|>':
        value = -1.27 if previous.strip().startswith('}') else (
            -0.31 if line_start else 0.0)

    return (doc, position + 1, (tail + token)[-256:], token), value

programs.haiku:
"""Layer 1 MLP down-projection, component 1170: a "list or steps are starting" detector.

Negative where the text opens an enumeration or a set of steps:
  - the first list label of a numbered list: the "." or ")" after a "1" (or "A", "I")
    at the start of a line (about -1.6; mid-line it is weak);
  - the first line of a reply right after its thinking block (about -1.9);
  - opening phrases: "Let me/Let's", "First,", "Here are", "below", "follows", "begin";
  - a colon, then a line break, which introduces a list, code or a table.
Positive where the text adds another option or point: "Alternatively", "Similarly",
"otherwise", "Also". Everything else is about 0.

Stateless: each value depends only on the current token and the two before it.
Values are typical activations (in the component's units) for each case.
"""

READS = ()

# Words that open a list or a sequence of steps, with their typical activation.
OPENING_WORDS = {
    "Let": -1.0, " Let": -1.0, " let": -0.5,
    "First": -0.9, " First": -0.45, " first": -0.25, "Firstly": -0.8, " Firstly": -1.1,
    "Here": -0.5, " Here": -0.5,
    "follows": -0.6, " follows": -0.6,
    "Below": -1.6, " below": -1.2,
    "begin": -0.6, "以下": -0.7, "如下": -1.0,
}
# Transitions that add another option or point: positive.
CONNECTIVE_WORDS = {
    "Alternatively": 0.85, " Alternatively": 0.8,
    "Similarly": 1.2, " Similarly": 1.2, " similarly": 0.4,
    "otherwise": 0.4, " otherwise": 0.45,
    " Also": 0.25, "Finally": 0.2, " Finally": 0.35,
}
# A colon then a line break introduces a list or a block.
COLON_BREAKS = {":\n\n": -0.45, ":\n": -0.25, ":\n\n\n": -0.8, "：\n\n": -0.7}
# Paragraph breaks: mildly negative.
PARA_BREAKS = {"\n\n": -0.2, ".\n\n": -0.2, "?\n\n": -0.25}
# Labels that start a list item, and the punctuation after them.
LABELS = {"1", "A", "I"}
LABEL_END = {".", ")"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    before = prefix.token_strings[-3] if len(prefix) > 2 else "\n"
    if cur in LABEL_END and prev.strip() in LABELS:
        # "1." at the start of a line opens a numbered list; mid-line it is weak.
        value = -1.6 if "\n" in before else -0.3
    elif cur == "\n\n" and prev == "</think>":
        value = -1.9                       # first line of a reply after its thinking block
    elif cur == "\n\n" and prev == "<think>":
        value = -0.85
    elif cur in OPENING_WORDS:
        value = OPENING_WORDS[cur]
    elif cur in CONNECTIVE_WORDS:
        value = CONNECTIVE_WORDS[cur]
    elif cur in COLON_BREAKS:
        value = COLON_BREAKS[cur]
    elif cur in PARA_BREAKS:
        value = PARA_BREAKS[cur]
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""A local grammar heuristic for the English leave family.

Leave/leaving are strongly negative. Preceding grammatical cues weaken
left in directional uses and leaves in foliage-like noun phrases.
There are also smaller token-split spelling rules for eum, euch and eav,
and a short response on 'the' immediately after a strong leave-family
response. Other tokens predict zero. History resets between documents.
"""
import re
import wordnet

READS = ()

SUBJECTS = set('i you he she it we they who which'.split())
POSSESSIVES = set('my your his her its our their whose'.split())
DIRECTION = set('from to on at in into toward towards top bottom upper lower '
                'far extreme right turn turns turning turned of for with before after '
                'inside outside between'.split())
BE = set('am is are was were been being'.split())
HAVE = set('have has had'.split())
DETERMINERS = set('the a an this that these those'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0.0)
    _, before, previous_token, previous_value = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    words = []
    if word in {'left', 'leaves'}:
        words = re.findall(r"[A-Za-z]+(?:['’][A-Za-z]+)?|\d+", before)
    prev = words[-1].lower() if words else ''
    value = 0.0

    if word == 'leave':
        value = -9.1
    elif word == 'leaving':
        value = -8.0
    elif word == 'leaves':
        noun = (prev in (DETERMINERS - {'this', 'that'}) | POSSESSIVES
                or before.lower().endswith("'s")
                or ('adjective' in wordnet.parts_of_speech(prev)
                    and prev not in {'still', 'just', 'only'})
                or wordnet.is_a(prev, 'plant')
                or wordnet.is_a(prev, 'season')
                or prev in {'of', 'with', 'in', 'from', 'to'})
        value = -3.2 if noun else -8.7
    elif word == 'left':
        if not token[:1].isspace():
            value = 0.25 if token == 'left' else -0.6
        elif prev == 'the':
            value = 0.1
        elif prev in POSSESSIVES | DIRECTION:
            value = -0.6
        elif prev in {'a', 'an'}:
            value = -1.7
        elif prev in SUBJECTS:
            value = -8.8
        elif prev in HAVE:
            value = -7.7
        elif prev == 'be':
            value = -6.2
        elif prev in BE:
            value = -4.8
        elif prev == 'or':
            value = -0.6
        elif prev in {'and', 'but'}:
            value = -4.6
        elif not before.strip() or before[-1:].isspace() and '\n' in before[-8:]:
            value = -0.8
        elif re.search(r'[=\\{}]|\b(?:def|const|int|bool)\b', before[-120:]):
            value = -0.6
        elif token.strip() != 'left':
            value = -0.8
        elif wordnet.parts_of_speech(prev) == {'adjective'}:
            value = -1.8
        elif prev.endswith('ed'):
            value = -2.8
        elif prev in {'already', 'indeed', 'then', 'just'}:
            value = -7.2
        elif (words and words[-1].istitle()) or prev.endswith('ly'):
            value = -7.2
        else:
            value = -4.0

    # Specific spelling families split by tokenization: e+um, le+ucht,
    # and le+aving or bere+aved. Do not treat a space as a word join.
    elif before.lower().endswith('e') and token[:1].isalpha():
        if token.lower() == 'um':
            value = 4.8
        elif re.fullmatch(r'ucht?', token.lower()):
            value = 7.0 if before.lower().endswith('le') else 5.0
        elif re.fullmatch(r'av(?:e(?:d|n|r|rs|s)?|ing)?', token.lower()):
            value = -8.5 if before.lower().endswith('le') else -5.5

    if word == 'the' and previous_token.strip().lower() in {
        'leave', 'left', 'leaves', 'leaving'
    } and previous_value < -3:
        value = 0.48 * previous_value

    return (doc, (before + token)[-180:], token, value), float(value)

programs.haiku:
"""Negative detector for the verb "leave" (go away, depart, abandon).

Layer 1's MLP down-projection, component 1171, writes a strong negative value into
the residual stream on the token that is the verb "leave" in its sense of going
away or quitting: "leave", "leaving", "leaves" (verb), and "left" as the past tense
("he left the room", "had left", "which left 20 dead"). It is near zero elsewhere.

Rules, in plain terms:
- "leave", "leaving": about -9 and -8.
- "leaves": the verb after a subject ("it leaves", "who leaves"): about -8.5; the
  plant noun after "the" or "their" (foliage): about -2; otherwise about -5.
- "left" right after a determiner or preposition ("the left side", "to the left",
  "turn left", "on her left") is the direction or position word, not the verb: about 0.
- other "left" after a subject or auxiliary ("he left", "I left", "had left", "was
  left") is the verb in its strongest form: about -6.8.
- any other "left" (for example "Susan has 8 apples left"): about -2.9.
- the word right after a verb "leave" or "left" is pulled a little negative when it
  is "the", "me", "his", "her", "it", "them", "a" or "its" (about -3).
- the "ave" piece after "le" (as in "Leavenworth", "leaven", or a split "LEAVE"): about -5.

Nothing else is predicted, so the component's small everyday wobble is ignored.
"""

READS = ()

LEAVE = {" leave", " Leave", " leaving", " Leaving"}
LEAVES = {" leaves", " Leaves"}
# words that, just before "left", make it a direction or position, not the verb
BEFORE_DIRECTION = {
    "the", "to", "on", "from", "her", "his", "my", "your", "its", "their", "our",
    "a", "turn", "top", "bottom", "right", "far", "or", "vs", "+",
}
# words that, just before "left", are a subject or auxiliary, so "left" is the verb
BEFORE_SUBJECT = {
    "i", "he", "she", "they", "we", "you", "who", "which", "that", "it", "had", "has",
    "have", "was", "were", "be", "been", "then", "finally", "already", "eventually",
    "indeed", "and", "is", "are",
}
OBJECT_WORDS = {" the", " me", " his", " her", " it", " them", " a", " its"}
AVE_PIECES = {"ave", "aven", "avel", "aves", "aver", "av"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    before_raw = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    before = before_raw.strip().lower()
    if before_raw in LEAVE or before_raw in LEAVES or before_raw == " left":
        if word in OBJECT_WORDS:
            return None, -3.0
    if word == " leave" or word == " Leave":
        return None, -9.0
    if word in LEAVE:
        return None, -8.0
    if word in LEAVES:
        if before in BEFORE_SUBJECT:
            return None, -8.5
        if before in BEFORE_DIRECTION:
            return None, -2.0
        return None, -5.0
    if word == " left":
        if before in BEFORE_DIRECTION:
            return None, -0.2
        if before in BEFORE_SUBJECT:
            return None, -6.8
        return None, -2.9
    if word.strip().lower() in AVE_PIECES and before.endswith(("le", "lea")):
        return None, -5.0
    return None, 0.0

programs.sol:
"""Approximate a mixed lexical response and its large document-onset offset.

Positive motifs are split Germanic temporal adverbs, Japanese adverbs, Romance
noun endings, and stars inside C comments.  Romance endings are gated by word
frequency so English words such as 'manure' do not trigger the French response.
An unchanged, repeated initial token retains the onset response.  These onset
classes deliberately omit the much larger token-specific variation.
"""
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()
KANA = regex.compile(r'[\p{Hiragana}\p{Katakana}]')
# German/Dutch: always, each time, continually, recently, mostly, always.
TEMPORAL = {'stets', 'jeweils', 'steeds', 'neuerdings', 'zumeist', 'immer'}
ENDINGS = {
    'ure', 'ures', 'ature', 'atures', 'atura', 'aturas', 'ura', 'uras',
    'age', 'ages',
}
# Of course, once, very, temporarily, usually, this time, definitely, entirely.
STRONG_JAPANESE = {
    '当然', '一度', '大変', 'いったん', '普段', '今度', '断然', '全然',
}
# Most, sufficiently, somewhat, why.
MODERATE_JAPANESE = {'一番', '充分', '若干', 'どうして'}


@lru_cache(maxsize=2048)
def romance_noun(word, stem):
    # Do not mistake frequent possessive prefixes (e.g. mes) for noun stems.
    if len(stem) < 3 or stem in {'mes', 'tes', 'ses', 'nos', 'vos'}:
        return False
    if word.endswith(('eure', 'eures')):
        return False  # Avoid competing -eure/-eures spellings.
    languages = (('it', 'es', 'pt') if word.endswith(('ura', 'uras'))
                 else ('fr',))
    frequency = max(zipf_frequency(word, language) for language in languages)
    return frequency >= 2.5 and frequency > zipf_frequency(word, 'en') + 1.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, word = 0, '', ''
        kana_at, comment, onset = -100, False, True
    else:
        _, position, previous, word, kana_at, comment, onset = carry
        onset = onset and token == previous
    if KANA.search(token):
        kana_at = position
    old_word = word
    if token and token[0].isspace():
        word = token.strip()
    elif token.isalpha():
        word += token
    else:
        word = token.strip() if token.strip().isalpha() else ''
    word = word[-32:]
    lower = word.lower()
    value = -0.002

    if onset:
        if token == '<|endoftext|>':
            value = -2.50
        elif token.startswith('<|'):
            value = -0.53
        elif token == '//\n':
            value = -2.45
        elif token.strip() == ';' and '\n' in token:
            value = 0.76
        elif token == '/*\n':
            value = -0.44
        elif token.strip().isdigit():
            value = -0.20
        elif not any(c.isalpha() for c in token):
            value = -0.22
        elif token.startswith(' '):
            value = -0.27
        else:
            value = -0.40
    elif token == ' *' and comment:
        value = (0.55 if '\r' in previous else 0.71) if position == 1 else 0.10
    elif token in ENDINGS and old_word and romance_noun(lower, old_word.lower()):
        value = 0.43
    elif lower in TEMPORAL:
        value = 0.60 if token.strip().lower() != lower else 0.22
    elif lower in {'nur', 'schon', 'erst', 'nun'}:
        value = 0.17 if lower == 'nur' else 0.27
    elif position - kana_at < 24 and any(
            (previous + token).endswith(w) for w in STRONG_JAPANESE):
        value = 0.63
    elif position - kana_at < 24 and any(
            (previous + token).endswith(w) for w in MODERATE_JAPANESE):
        value = 0.50
    elif token == 'まず':
        value = 0.23
    elif (previous + token).endswith('改めて'):
        value = 0.31
    elif token == '偏':  # Chinese: deviation, or the degree adverb 'rather'.
        value = 0.50
    elif token == '://':
        value = -0.13
    elif token.strip() == 'import':
        value = 0.11 if token.startswith(' ') else 0.05
    elif token in {'<tool_response>', '</tool_response>', '<think>'}:
        value = -0.08
    elif token == '<|im_start|>':
        value = -0.04
    elif token == '<tool_call>':
        value = 0.05

    if '/*' in token:
        comment = position == 0
    if '*/' in token:
        comment = False
    return (doc, position + 1, token, word, kana_at, comment, onset), value

"""Approximate a mixture of short formatting continuations, not a topic.

Negative pulses mark early, unindented answer labels, numbered Markdown
headings, and standalone web prompts ('View more', 'Read more', timestamps).
Blank-line-separated or indented letters are different from answer labels.
Display-math line breaks and 'More from' have positive pulses. Small initial
baselines depend on character type; most ordinary text is predicted near zero.
Only a short line suffix and the last two tokens are remembered, per document.
"""
import math
import re
import unicodedata

READS = ()
SHORT_TIME = r'\d+\s+(?:second|minute|hour)s?'


def initial_value(token):
    word = token.strip()
    if token.isspace():
        if '\n' in token:
            return -0.11
        return 0.5 if '\t' in token else 0.39 if len(token) > 1 else -0.26
    if word.isascii() and word.isalpha():
        if token[0].isspace():
            return 0.08 if word[0].isupper() or len(word) == 1 else -0.05
        return -0.28 if word[0].isupper() or len(word) == 1 else -0.07
    if word.isdigit():
        return 0.07
    return -0.07 if all(unicodedata.category(c)[0] == 'P' for c in word) else -0.18


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, earlier, line = 0, '', '', ''
    else:
        _, position, previous, earlier, line = carry
    token = prefix.token_strings[-1]
    word, before = token.strip(), previous.strip()
    clean_line = unicodedata.normalize('NFKC', line)
    value = initial_value(token) if position == 0 else 0.0007

    if token == '.' and re.fullmatch(r'\s*[A-Za-z]\s*', clean_line):
        single_break = earlier.endswith('\n') and earlier.count('\n') == 1
        if clean_line in 'ABCDE' and single_break:
            value = -0.4 - 0.9 * math.exp(-position / 64)
        else:
            value = 0.12
    elif word in {'##', '###'} and re.fullmatch(r'\d+\.', line):
        short_number = len(line) <= 2
        value = (-1.2 if short_number else -0.5) if word == '###' else -0.6
    elif word in {'more', 'More'}:
        if line == 'View':
            value = -6.8 if word == 'more' else -5.3
        elif line == 'Read':
            value = -1.85 if word == 'more' else -0.93
        elif line == 'Learn' and word == 'more':
            value = -1.4
        elif before.lower() == 'see':
            value = -0.75
        elif previous == 'View':
            value = -0.5
    elif word == 'ago' and re.fullmatch(SHORT_TIME, line):
        value = -1.3
    elif token == ':' and previous == 'Title' and position == 1:
        value = -5.74
    elif token.isspace() and '\n' in token and line == '$$':
        value = 0.9
    elif word == 'from' and line == 'More':
        value = 1.5
    elif word == 'Results' and line == 'Search':
        value = -1.7
    elif token.startswith(':') and line == 'Posted':
        value = -1.5 if '\n' in token else 0.75
    elif word == '%%' and before == '#':
        value = -1.0
    elif token == previous and token and set(token) == {'·'}:
        value = -0.616

    line = (line + token).rsplit('\n', 1)[-1][-128:]
    return (doc, position + 1, token, previous, line), float(value)

programs.haiku:
"""Sparse readable model of one MLP down-projection component in layer 1.

The component is almost silent. Its activation is near zero at most tokens, with a
few kinds of event that carry most of its variance:

1. The first token of each document (or of a packed row). The model sees nothing before
   it, so its activation depends only on what the token looks like. Capitalised words,
   symbols and CJK text push it negative; indented or space-led code-like text pushes it
   positive.
2. The word "more" in a "Read more" / "View more" / "Learn more" link, which is strongly
   negative.
3. A "###" markdown header that follows a numbered list item such as "3. ###", also
   strongly negative.

Everywhere else the program predicts 0. The rest of the activation is small diffuse
noise with no token or character pattern that a short rule can capture.
"""

READ_MORE_LEADS = {"Read", "Learn", "View", "See", "Click", " Read", " Learn", " View", " See", " Click"}


def first_token_value(s):
    """Typical activation of a document's first token, by how it looks."""
    if s == "" or "�" in s:
        return 0.0
    body = s.strip()
    if body == "":
        return 0.3 if len(s) > 1 else -0.2  # indentation vs a lone space
    if any(ord(c) > 0x2E80 for c in body):
        return -0.3  # CJK or other non-Latin script
    if body[0].isalpha():
        if s[0] == " ":
            return -0.07 if body[0].islower() else 0.05
        return -0.25 if body[0].isupper() else -0.15
    if body[0].isdigit():
        return 0.08
    return 0.15 if s[0] == " " else -0.1


READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    n = len(prefix.token_ids)
    if n == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, float(first_token_value(s))
    if s == " more" and prefix.token_strings[-2] in READ_MORE_LEADS:
        return carry, -1.1
    if s == " ###" and prefix.token_strings[-2] == ".":
        return carry, -1.1
    return carry, 0.0

programs.sol:
"""Recognize heading-ending line breaks, rather than ordinary paragraph text.

Bibliographic section titles give a strong negative response.  Markdown
headings and short, letter-dense, noun-ending lines give smaller responses;
blank lines and capitalization help distinguish headings from wrapped prose.
Decorative heading delimiters are negative too; quote-ending line breaks
are positive. Chat tags and an opening Title label have boundary responses.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
BIBLIOGRAPHIC_HEADINGS = {
    'references', 'external links', 'see also', 'notes', 'footnotes',
    'citations', 'sources', 'bibliography', 'further reading',
}


@lru_cache(maxsize=4096)
def is_noun(word):
    return bool(word) and 'noun' in wordnet.parts_of_speech(word)


def line_break(line, previous, count, blank_before, token):
    text = line.strip()
    title = re.sub(r'^#{1,6}\s+', '', text).lower()
    if title in BIBLIOGRAPHIC_HEADINGS:
        return -3.47
    if previous == '</think>':
        return -0.52
    if previous == '<tool_response>':
        return -0.27
    if re.fullmatch(r'={3,}\s+.+\s+={3,}', text):
        return -2.0
    letters = [c for c in text if c.isalpha()]
    density = len(letters) / max(1, len(text))
    capitals = sum(c.isupper() for c in letters) / max(1, len(letters))
    markdown = bool(re.match(r'^\s*#{1,6}\s', line))
    if markdown:
        if count <= 3:
            return -1.65 if capitals < 0.13 else -0.80
        if token.count('\n') > 1 and len(text) < 40:
            return -0.47
        return 0.0
    if density > 0.874:
        if not blank_before:
            return -0.22 if capitals > 0.019 else 0.0
        words = re.findall(r'[A-Za-z]+', text)
        if not words or not is_noun(words[-1].lower()):
            return -0.13
        if density <= 0.922:
            return -0.46
        return -1.36 if capitals < 0.215 else -0.39
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, previous, count, blank_before, position = '', '', 0, False, 0
    else:
        _, line, previous, count, blank_before, position = carry
    # Escaped newlines also separate headings in quoted text and tool output.
    token = prefix.token_strings[-1].replace('\\n', '\n')
    value = 0.0
    if '\n' in token and not token.strip():
        value = line_break(line, previous, count, blank_before, token)
    elif position == 1 and line == 'Title' and token == ':':
        value = 12.5
    elif token == '¶':
        value = -2.6
    elif re.fullmatch(r"[ >}\].!?]*['\"]\r?\n+", token):
        value = 0.4
        if "'" in token and (token.startswith(' ') or '>' in token):
            value = 2.5
    elif (re.fullmatch(r'={3,}', token.strip())
          and re.match(r'^\s*={3,}\s+\w', line)):
        value = -0.75
    if '\n' in token:
        line = (line + token).rsplit('\n', 1)[-1]
        blank_before = token.count('\n') > 1
        count = 0
    else:
        line = (line + token)[-500:]
        count += 1
    return (doc, line, token, count, blank_before, position + 1), value

"""Local phrase, character-spelling and typography rules.

Negative peaks include 'for instance', isolated Han characters such as
奇/妙, selected compounds, and 空間/空间 (spatial room). Dash responses
use their left context. Document-opening labels and repeated middle dots
have separate rules.

Some tokens spell only part of a character: recent bytes identify three
completed spellings and two shared Han prefixes. Context resets at document
boundaries. Most tokens receive zero. This approximates conspicuous training
peaks, not the many small, diffuse responses.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, previous2, position, tail = '', '', 0, b''
    else:
        _, previous, previous2, position, tail = carry
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    tail = (tail + raw)[-12:]
    value = 0.0

    if token == ' instance' and previous.strip().lower() == 'for':
        value = -1.35
    elif token in ('奇', '妙'):
        value = -2.25
    elif token in ('幽', '趣', '异'):
        value = -0.9
    elif token == '異':
        value = -0.5
    elif token == '幻':
        value = -0.5
    elif token in ('神奇', '奇幻', '巧妙', '奇妙'):
        value = -0.8
    elif token == '空間':
        value = -1.4
    elif token == '空间':
        storage = ('存储', '储存', '内存')
        value = -0.2 if previous.endswith(storage) else -1.65
        if 'printf' in previous2:
            value = -0.6
    elif token == '的空间':
        value = -2.2
    elif token == '尺度':
        value = -0.5
    elif token == '飞':
        value = -0.3
    elif token == '··':
        value = 0.99
    elif token == 'xc' and previous.endswith('\\'):
        value = -0.9
    elif token == ':' and previous == 'Title' and position == 1:
        value = -2.46
    elif token == 'package' and position == 0:
        value = -1.63
    elif token == '—':
        if previous.endswith('\n'):
            value = 0.7 if previous.endswith('.\n') else 1.4
        elif previous.isspace():
            value = 1.2
        elif previous[-1:].isdigit() or previous.endswith('('):
            value = 0.85
    elif token == ' —':
        last = previous[-1:]
        value = -0.07
        if last and not last.isalpha():
            value = 0.3
        elif last and not last.isascii():
            value = 0.25
    elif token == ' –':
        value = 0.12 if previous[-1:].isdigit() else -0.02
    elif token == '–':
        value = 0.4 if previous.endswith('\n') else -0.08

    # Tokenization sometimes exposes only part of a character's spelling.
    if len(raw) == 1 and 0x80 <= raw[0] < 0xC0:
        if tail.endswith('そ'.encode()):
            value = 1.4
        elif tail.endswith('関'.encode()):
            value = 0.7
        elif tail.endswith('趣'.encode()):
            value = -1.2
        elif tail.endswith(b' ' + '雅'.encode()[:2]):
            value = -1.2
        elif tail.endswith(b' ' + '隐'.encode()[:2]):
            value = -2.2

    if position == 0:
        if token and set(token) == {'#'} and len(token) <= 3:
            value = -0.2 * (len(token) + 1)
        elif token == '//':
            value = -0.68
        elif token == 'Q':
            value = -0.67
        elif token == '\t':
            value = 0.65
        elif token == '\n':
            value = 0.31

    return (doc, token, previous, position + 1, tail), value

programs.haiku:
"""Layer 1 MLP down-projection, component 1176: a sparse, word-specific detector.

Plain-language summary
- It is mostly quiet (near 0). It goes clearly NEGATIVE on a few words:
  * CJK words for "strange / mysterious / wondrous" (奇, 奇幻, 神奇, 奇妙, 幽, 幻, 妙, 趣, 异, 險 ...),
  * the Chinese word for "space" (空间 / 空間),
  * "instance" in the phrase "For instance" (about -1.3; bare "instance" is ~0),
  * "package" at the start of a document (code file start),
  * other code openers at a document start ("#", "#include", "//", "##").
- It goes POSITIVE on an em dash "—" (strongest at the start of a line, after a
  newline or a number).
- Long runs of the middle-dot filler "··" (100+ in a row, a degenerate repetition)
  push it strongly positive (about +0.8); short runs stay near 0.
- The program predicts the activation from the current token and a little context
  (previous token; whether the token opens a document; length of a run of "··").

Values are rough means measured on training text; they are not fitted to eval.
"""

READS = ()

STRANGE_WORDS = {"奇", "奇幻", "神奇", "奇妙", "幽", "幻", "妙", "巧妙", "趣", "有趣", "异", "異", "險", "险"}
SPACE_WORDS = {"空间", "空間", "的空间"}
CODE_OPENERS = {"#", "#include", "//", "##", "*", "["}
FOR_PREVIOUS = {" For", " for"}
NEWLINE_BEFORE = {"\n", ".\n"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix) > 1 else ""
    opens_document = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    # length of the current run of middle dots, reset at each new document
    run = carry if (carry is not None and not opens_document) else 0
    run = run + 1 if token == "··" else 0

    value = 0.0
    if run >= 100:
        value = 0.8
    elif token in STRANGE_WORDS:
        value = -1.0
    elif token in SPACE_WORDS:
        value = -1.5
    elif token == " instance" and previous in FOR_PREVIOUS:
        value = -1.3
    elif opens_document and token == "package":
        value = -1.6
    elif opens_document and token in CODE_OPENERS:
        value = -0.6
    elif token == "—":
        value = 1.0 if previous in NEWLINE_BEFORE else 0.3
    return run, float(value)

programs.sol:
"""Predict spikes at first-person proposals and future-action announcements.

Respond on me/us after 'let', on the ending of "let's", and on will,
shall or 'll after I/we. Capitalization changes their typical strength.
Reported permission ('they let us', 'wouldn't let us') is not a proposal;
'Please let me' is a weaker, polite request. Other tokens stay near zero.
Only two previous tokens are kept, resetting at document boundaries.
"""
READS = ()

# Subjects, auxiliaries and negatives that make 'let' a permission report.
PERMISSION_CUES = {
    'i', 'we', 'you', 'he', 'she', 'it', 'they',
    'can', 'could', 'may', 'might', 'must', 'should', 'would',
    'will', 'shall', "'ll", '’ll', 'have', 'has', 'had', 'to',
    'not', 'never', "'t", '’t', "n't",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
