"""A whitespace-formatting detector, rather than a topical feature.

The second of two separate space tokens is positive in prose. It is weak in
leading indentation, stronger near a document's start, and stronger on long
lines. Two- and four-space indentation after line breaks is usually negative.
Two spaces after a digit or period get a small positive response. Other
tokens are left at zero; lexical responses are not modeled. Prose-like lines
are identified by counting ASCII alphabetic tokens, not by reading their topic.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous, position, words, length = '', '', 0, 0, 0
    else:
        _, previous, before_previous, position, words, length = carry
    text = prefix.token_bytes[-1].decode('utf-8', 'replace')
    spaces = len(text) if text and not text.strip(' ') else 0
    value = 0.0

    if text == ' ' and previous == ' ':
        if length <= 2 or position <= 1:
            value = 0.05
        elif words < 2:
            value = 1.3
        elif position < 80:
            value = 4.1
        elif length < 200:
            value = 2.2
        else:
            value = 1.4 if before_previous.strip().isdigit() else 3.2
    elif spaces and previous.endswith(('\n', '\\n')):
        ending = previous.rstrip('\r\n')
        if spaces == 2:
            value = -1.4 if ending.endswith(' ') else (
                -0.8 if ending.endswith(':') else -0.25)
        elif spaces == 4:
            value = -0.8 if ending.endswith(' ') else -0.17
        elif spaces == 3:
            value = -0.4 if ending.endswith(' ') else -0.08
        elif spaces == 1:
            value = -0.3
    elif spaces == 2:
        if previous[-1:].isdigit() or previous.endswith('.'):
            value = 0.8

    # Track the current line, treating printed backslash-n as a line break too.
    if '\n' in text or '\\n' in text or (previous == '\\' and text == 'n'):
        tail = text.split('\n')[-1].split('\\n')[-1]
        length, words = len(tail), 0
    else:
        length = min(200, length + len(text))
        word = text.strip()
        words = min(12, words + int(word.isascii() and word.isalpha()))
    return (doc, text, previous, position + 1, words, length), value

