    'align': (0.4475, 1.6959),
    'aligned': (-0.7414, 1.4734),
    'array': (0.3487, 0.5764),
    'cases': (0.2230, 0.5026),
    'split': (-0.4988, 0.3576),
    'matrix': (0.2887, 0.8272),
    'atrix': (0.5817, 1.1459),  # tokenizer splits "pmatrix" as pm + atrix
