        if re.search(r'(?:^|\n)\d+$', before):
            proof = ' . .' in before or 'StepHypRef' in before
            return -6.0843 if proof else -2.2904
        if before.endswith('\xa0'):
            return -0.0131
        return -0.1841 if before and before[-1].isdigit() else -0.1311

    if word in COUNTERS:
        number = re.search(r'(\d[\d,\.]*[kKmM]?)$', before)
        if number:
            lead = before[:number.start()]
            if word.lower() == 'views':
                compact = lead.endswith('\n') and not lead.endswith('\n\n')
                return 0.5135 if compact else 4.0965
            return 2.2891 if word.lower() == 'likes' else 0.1553
        if word == 'badges' and before.endswith(('bronze', 'silver', 'gold')):
            return 2.2900

