        return 0.2578
    if word == 'Scholar' and before.endswith('Google'):
        return 1.4279
    if word == 'protected' and re.search(r'\[email\s*$', before):
        return 1.4450
    if token == '/issues':
        return 0.5855
    if token == '/licenses':
