    if token == '/MPL' and 'mozilla.org' in before:
        return 3.1967
    if word == 'SOFTWARE' and 'DEALINGS' in before:
        return 6.1171
    if word == 'DAMAGE' and 'SUCH' in before:
        return 4.4209
    if word == 'License':
        if before.endswith('under the'):
            return 1.2831
        if before.endswith('GNU General Public'):
