        return 1.0876
    if token == '-' and re.search(r'\d{4}(?:-\d{1,2})?$', before):
        return 0.1419
    if word == 'Expression' and before.endswith('Ref'):
        return -2.5462
    if word == 'Questions' and before.endswith('Homework Help'):
        return -3.9941
    if word == 'username' and before.endswith('<issue_comment>'):
        return -3.3086
    if word == 'issue':
