"""Layer 1, MLP down_proj, component 1180.

Mostly silent. It responds to a few recognisable spots in web pages and code:

* a non-breaking space (U+00A0) right after a line number at the start of a line, as in a
  numbered code listing ("...;\\n2598\\xa0 for"): strongly negative;
* a view or like counter word ("views", "likes") right after its number ("1,789 views"):
  strongly positive;
* a LaTeX environment name (align, aligned, matrix, array, cases) closing an environment,
  right after "\\end{": positive; after "\\begin{": mildly positive, except "aligned",
  which is mildly negative there;
* "License" in the licence-header phrases "under the License" and "Public License": mildly
  positive;
* a markdown backtick that follows code-like text (a symbol, "int", a semicolon, an indent):
  mildly positive.

Other non-breaking spaces get a small negative value (numbers split by spaces, indents), and
every other position predicts 0. The program reads the newest token and the few before it,
so it is causal.
"""
import re

READS = ()

NUMBER = re.compile(r"[\d,.]*\d[\d,.]*")
DIGITS = re.compile(r"\d+")
COUNTERS = {"views", "Views", "likes", "Likes"}
LATEX_ENVS = {"align", "aligned", "matrix", "array", "cases"}
CODE_BEFORE = {" `", "`", "``", ";", ")", "(", "{", "=", "int", "\xa0", " \xa0"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    prev2 = toks[-3] if len(toks) > 2 else ""
    after_number = bool(NUMBER.fullmatch(prev.strip()))
    value = 0.0
    if cur.strip() in COUNTERS and after_number:
        value = 3.2
    elif cur == "\xa0":
        # digits run back from the NBSP: a line number at the start of a line?
        k = len(toks) - 2
        while k >= 0 and DIGITS.fullmatch(toks[k]):
            k -= 1
        if k == len(toks) - 2:
            value = -0.1
        elif k >= 0 and "\n" in toks[k]:
            value = -2.8
        else:
            value = -0.2
    elif cur.strip() in LATEX_ENVS and prev == "{" and prev2 == "end":
        # the name closing an environment, e.g. \end{align}
        value = 1.2
    elif cur.strip() in LATEX_ENVS and prev == "{" and prev2 == "begin":
        value = -0.8 if cur.strip() == "aligned" else 0.4
    elif "`" in cur and (prev in CODE_BEFORE or prev.startswith("\xa0")):
        value = 0.4
    elif cur.strip() == "License" and (prev.strip() == "Public" or (prev.strip() == "the" and prev2.strip() == "under")):
        # licence headers: "under the License", "GNU General Public License"
        value = 1.3
    return carry, float(value)

