def onset_value(token):
    if token == '<|endoftext|>':
        return 6.66
    if token == '<|im_start|>':
        return -3.35
    word = token.strip().lower()
    if not word:
        return 1.9 if '\t' in token else -0.8
    if word in {'these', 'those'}:
        return 12.5
    if word in PLURAL_QUANTIFIERS or word in {'are', 'were'}:
        return 5.5
    if word in NUMBER_WORDS:
        return 7.0
    if word in {'and', 'or'}:
        return 3.8
    if word == 'with':
        return 6.0
    if word in {'a', 'an'}:
        return -4.0
    if word in {'this', 'that', 'the'}:
        return -2.9
    if word in PREPOSITIONS:
        return -3.0
    if word in IMPORT_DIRECTIVES:
        return -4.5
    if word in {'we', 'us', 'our', 'they', 'them', 'their'}:
        return 0.0
    if word.isdecimal() and word.isascii():
        number = int(word)
        return -1.3 if number < 3 else 1.0
    if word[0] in '([{':
        return -3.0
    if word[0] in ')]}':
        return 0.5
    if not any(c.isalpha() for c in word):
        return -0.8
    if not word.isascii():
        return -1.4
    # A small spelling model for otherwise unclassified initial tokens.
    value = -0.7 + 1.7 * (len(word) == 1) - 1.2 * token.strip().istitle()
    value -= 3.2 * ('p' in word) + 2.4 * word.startswith('p')
    value -= 2.4 * ('k' in word) + 1.4 * any(c in word for c in 'mb')
    value += 2.2 * ('v' in word)
