PRONOUNS = {"it", "its", "he", "she", "we", "you", "they", "one", "who", "than", "other", "those"}
AUX_AND_INTENSIFIERS = {
    "be", "being", "been", "do", "does", "did", "may", "can", "would", "should", "will",
    "using", "use", "used", "many", "very", "even", "two", "several", "well", "also",
}
FUNCTION_WORDS = {
    "with", "at", "from", "in", "into", "through", "of", "to", "for", "on", "by", "about",
    "like", "and", "or", "that", "what", "each", "some", "no", "your", "their", "my", "our",
    "more", "only", "then", "first", "the", "a", "an", "is", "are", "was", "were", "this", "there",
}
CLOSERS = set(")]}\"'`;")

# Typical activation per class (fit on sample text; see explanation).
VALUE = {
    "doc_start": -2.0,
    "partial_byte": 0.5,
    "pronoun": 0.8,
    "aux": 0.45,
    "non_ascii": 0.33,
    "closer": 0.24,
    "word_fragment": 0.2,
    "spaced_word": 0.16,
    "punct": 0.1,
    "function_word": 0.0,
    "digits": 0.0,
}


def _kind(text):
    if "�" in text:
        return "partial_byte"
    word = text.strip().lower()
    if word in PRONOUNS:
        return "pronoun"
    if word in AUX_AND_INTENSIFIERS:
        return "aux"
    if word in FUNCTION_WORDS:
        return "function_word"
    if not word:
        return "punct"
    if word.isdigit():
        return "digits"
    if any(ord(c) > 127 for c in word):
        return "non_ascii"
    if all(unicodedata.category(c)[0] in "PS" for c in word):
        return "closer" if word[-1] in CLOSERS else "punct"
    if all(c.isalpha() for c in word):
        return "spaced_word" if text[:1] == " " else "word_fragment"
    return "punct"


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, VALUE["doc_start"]
    return carry, VALUE[_kind(prefix.token_strings[-1])]

"""Research-question framing detector.

Component p-82af68dd@100000/layers.1.mlp.down_proj:1184 is mostly negative, and its
large negative values sit on the words that set up what a piece of writing is
going to examine: "to see IF the drug works", "we investigated WHETHER ...",
"the aim of this study is TO assess THE ...", "the effect OF ...", "an analysis
OF ...". It is near zero on ordinary text. A run of middle dots "··" (a repeated
filler token) gives a steady positive value.

The program reads the current word and the words just before it, within the same
document:
  * an inquiry verb (investigate, examine, assess, aim, study, compare, ...) is
    itself negative: strongest for investigate/examine/assess/aim, weaker for the rest;
  * a question word (if, whether, how, what) right after an inquiry cue is
    strongly negative, less so 2 to 4 words after, and weakly negative 5 to 8
    words after;
  * a linking word (the, to, of, this, which) right after an inquiry cue is
    moderately negative, less so 2 to 4 words after;
  * a "purpose or analysis" noun (analysis, influence, purpose, goal, ...) counts
    as a distant cue only.
Everything else is 0. The values are rounded least-squares fits on training rows.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Strongest cues: investigating, examining, assessing and aiming.
TOP_CUE = {"investigate", "investigated", "investigating", "examine", "examined",
           "examining", "assess", "assessed", "aim", "aims", "aimed"}
# Other inquiry verbs and nouns: studying, comparing, evaluating, testing, determining.
STRONG_CUE = {
    "evaluate", "evaluated", "evaluating", "compare", "compared", "comparing",
    "study", "studied", "studying", "determine", "determined", "hypothesis", "tested",
    "explored", "analyze", "analyzed", "verify", "quantify", "characterize", "investigations",
}
# Weaker cues: checking, seeing, testing, wondering, measuring, effects.
WEAK_CUE = {
    "effect", "effects", "test", "testing", "check", "see", "find", "understand",
    "measure", "measured", "wonder", "wondered", "wondering", "curious", "interested", "ask",
}
# Purpose and analysis nouns: they start a question but are not inquiry verbs.
DISTANT_CUE = {
    "analysis", "influence", "impact", "effectiveness", "accuracy", "evaluation",
    "assessment", "purpose", "goal", "objective", "objectives", "seek", "seeks",
    "address", "explore", "review", "focus", "problem", "question", "questions",
}
CUE = TOP_CUE | STRONG_CUE | WEAK_CUE | DISTANT_CUE
QUESTION_WORDS = {"if", "whether", "how", "what"}
LINK_WORDS = {"the", "to", "of", "this", "which"}


def _word(text: str) -> str:
    return text.strip().lower()


def _cue_distance(prefix, t: int, reach: int = 8) -> int:
    """Words back to the nearest cue in this document (0 if there is none)."""
    for k in range(1, reach + 1):
        j = t - k
        if j < 0 or prefix.document_ids[j] != prefix.document_ids[t]:
            return 0
        if _word(prefix.token_strings[j]) in CUE:
            return k
    return 0


def step(carry, prefix, upstream: Mapping):
    t = prefix.position
    word = _word(prefix.token_strings[t])
    if word == "··":
        return carry, 1.8
    if word in TOP_CUE:
        return carry, -2.5
    if word in STRONG_CUE:
        return carry, -1.1
    if word in WEAK_CUE:
        return carry, -0.2
    dist = _cue_distance(prefix, t)
    if dist and word in QUESTION_WORDS:
        return carry, -2.5 if dist == 1 else -1.1 if dist <= 4 else -0.4
    if dist and word in LINK_WORDS:
        return carry, -1.1 if dist == 1 else -0.3 if dist <= 4 else 0.0
    return carry, 0.0

"""Candidate v5: broader technology/method vocabulary."""
READS = ()

METHOD_NOUNS = {
    "technique", "techniques", "technology", "technologies", "method", "methods",
    "methodology", "approach", "approaches", "algorithm", "algorithms", "tool", "tools",
    "material", "materials", "agent", "agents", "therapy", "therapies", "treatment",
    "treatments", "architecture", "architectures", "solution", "solutions", "combination",
    "ingredients", "circuit", "circuits", "chip", "chips", "ai", "design", "designs",
    "product", "products", "software", "device", "devices", "plugin", "platform",
    "compound", "compounds", "inhibitor", "inhibitors", "drug", "drugs",
    "技术", "方法", "材料", "模型", "法", "装置", "治療", "療", "剂",
}
NOVELTY_ADJS = {
    "proposed", "novel", "innovative", "advanced", "conventional", "traditional", "neural",
    "artificial", "modified", "popular", "powerful", "efficient", "designed", "developed",
    "installed", "enabled", "revolutionary", "inexpensive", "-based",
}
EXAMPLE_WORDS = {"like", "as", "or", "called"}
POSITIVE_WORDS = {"between", "data", "set", "than", "within"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word == "as" and before == "such":
        value = -0.6
    elif word in EXAMPLE_WORDS and before in METHOD_NOUNS | NOVELTY_ADJS:
        value = -0.3
    elif word in METHOD_NOUNS:
        value = -0.3
    elif word in NOVELTY_ADJS:
        value = -0.1
    elif word in POSITIVE_WORDS:
        value = 0.03
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Short collocations, web-page furniture, and code-fragment boundaries.

This is a sparse predictor: it recognizes a few ordinary phrase families,
page/count labels, numeric size suffixes and social-link notation.  It also
has separate rules for the first token of a document.  It is not a general
semantic classifier; unrecognized text has prediction zero.  This is a
partial explanation, leaving most lexical variation unmodeled.
"""
import re

READS = ()

# Endings of familiar web interface labels, in several languages.
PAGE_ENDINGS = {
    'Post navigation': 1.0,
    'Continue reading': 0.5,
    'Weiterlesen': 0.7,  # Read more.
    'Herunterladen': 1.0,  # Download.
    '繼續閱讀': 0.9,
    '继续阅读': 0.9,
    '上一页': 1.1,
    '下一页': 1.1,
    'Leave a': 0.6,
    'All times': 0.5,
    'This content was': 1.0,
    'You have Successfully': 1.2,
    '收起': 1.3,  # Collapse/less.
}


def predict(token, tail, text, first):
    if first:
        # Common beginnings of source-code documents.
        if token == 'import':
            return -0.84
        if token == 'def':
            return -1.14
        if token == '#include':
            return -0.4
        if token.startswith('/*'):
            return -0.94 if '\n' in token else -0.47
        word = token.strip()
        if word.isascii() and word.isdigit():
            return 0.23
        if len(word) == 1 and word.isascii() and word.isupper():
            return 0.25
        if word.lower() in {'a', 'an', 'the'}:
            return 0.23
        if token == '<|im_start|>':
            return 0.31
        if token == '<|endoftext|>':
            return -1.03
        if token == '.':
            return 0.27
        if token == 'Person':  # Generic subject of an action caption.
            return -1.1
        if token.strip() == 'Not':
            return 0.85
        if token.strip() == 'Despite':
            return -1.0
        if token == ' .':
            return -1.8
    if token == '··' and tail.endswith('··'):
        return -1.47
    if token == ':' and re.search(r'(?:^|<\|endoftext\|>)Title$', tail):
        return -1.25
    if token == ' of':
        word = re.search(r'(\w+)$', tail)
        word = word[1].lower() if word else ''
        if word == 'rest':
            return 0.35
        if word == 'part':
            if re.search(r'\bfile is part$', tail, re.I):
                return 0.95
            if re.search(r'\b(?:is|are|was|as) a part$', tail, re.I):
                return 0.32
            if re.search(r'\b(?:is|are) part$', tail, re.I):
                return 0.16
            return -0.03
        if word == 'out':
            return 0.42 if re.search(r'\d+ out$', tail) else -0.09
        if word == 'end':
            return 0.1 if re.search(r'\bat the end$', tail, re.I) else 0.0
        return 0.0
    if token == ' ' and re.search(r'\bPage \d+ of$', tail):
        return 0.9
    if token.strip() in {'K', 'k', 'KB'} and tail[-1:].isdigit():
        if token.strip() == 'KB':
            return 1.0
        return 0.65 if re.search(r'\bViews\b', tail) else 0.05
    if token in {' ##', ' ###'} and re.search(r'\d\.\s*$', tail):
        return 0.45
    if '@' in token:
        if token == ' (@':
            return -0.53
        if re.search(r'\bTwitter(?: at)?\s*$', tail):
            return -1.3
    if token == '次数':  # Counts of downloads, views or uses.
        if tail.endswith(('下载', '浏览')):
            return 2.0
        return 0.9 if tail.endswith('使用') else 0.4
    if token == ' yet':
        if re.search(r"n['’]t$", tail, re.I):
            return 0.65
        if re.search(r"(?:\bnot\b|n['’]t\b|\bno\b)[^.!?\n]{0,48}$", tail, re.I):
            return 0.28
    if token == ' was' and tail.endswith('This post') and 'KUDOS' in tail:
        return 1.2
    if token == ' here' and re.search(r'\bclick$', tail, re.I):
        return -0.42
    if token == ' free' and tail.endswith('online'):
        return -0.65
    if token == ' to' and re.search(r'\bclick here$', tail, re.I):
        return -0.55
    if token == ' miss' and re.search(r"(?:^|\n)Don't$", tail):
        return 0.4
    for phrase, value in PAGE_ENDINGS.items():
        if text.endswith(phrase) and not tail.endswith(phrase):
            return value
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = b'' if first else carry[1]
    current = prefix.token_bytes[-1]
    tail = previous.decode('utf-8', 'replace')
    text = (previous + current).decode('utf-8', 'replace')
    value = predict(prefix.token_strings[-1], tail, text, first)
    return (doc, (previous + current)[-384:]), value

"""An approximate detector of exposed 'lo' syllables in word pieces.

The main response is negative.  It is strongest in short pieces ending in 'lo',
when initial 'o' joins a preceding final 'l', and on a short continuation of
'lo'.  Merged, familiar words are much weaker evidence.  Transliteration
extends the same rules to other alphabets; a few syllabic scripts spell
lo/ro as a single character instead.  Common scientific '-ology' endings
receive a small positive response.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=32768)
def properties(raw):
    # Arabic waw is the spelling of the rounded vowel in 'lo/lu'.
    s = anyascii(raw.replace('و', 'o')).lower()
    w = s.strip()
    latin = all('LATIN' in unicodedata.name(c, '')
                for c in raw if c.isalpha())
    return s, w, zipf_frequency(w, 'en'), latin


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    s, w, frequency, latin = properties(raw)
    n = len(w)
    value = 0.003
    if 'lo' in w:
        if w.endswith('lo'):
            if n <= 3:
                value = -1.1 if not latin else (
                    -2.4 if s.startswith('l') else -1.6)
            else:
                value = -0.65 if n == 4 else -0.05
        elif s.startswith('l') and n <= 3:
            value = -0.4 if 3 < frequency <= 4.5 else -1.5
        elif n <= 5:
            value = -0.7 if frequency <= 3.5 else -0.12
            if not w.startswith('lo'):
                value *= 0.5
        else:
            value = 0.15 if w.startswith('olog') else -0.04
    elif previous.endswith('l') and s.startswith('o'):
        if n <= 2:
            value = -2.65 if frequency <= 5.5 or not latin else -0.65
        else:
            value = (-0.75 if latin else -1.85) if n <= 4 else -0.3
    elif previous.endswith('lo') and s[:1].isalpha():
        if frequency > 2:
            value = -1.2 if n <= 2 else -0.5
    elif 'lo' in previous and s.startswith('o'):
        value = -0.55 if n <= 2 else -0.08

    if re.fullmatch(r'olog(?:y|ies|ists?|ic(?:al(?:ly)?)?)', w):
        value = 0.15

    # Syllabic spellings of lo/ro, not Latin letter sequences.
    if 'ロ' in raw:
        value = -1.8 if len(raw.strip()) == 1 else (
            -1.1 if len(raw.strip()) == 2 else -0.3)
    elif 'ろ' in raw:
        value = -0.45
    elif '로' in raw:
        value = -0.9 if len(raw.strip()) == 1 else -0.2
    elif 'لو' in raw:
        value = -2.5 if len(raw.strip()) == 2 else -0.3
    return (doc, s), value

"""Local digit-pair and letter-label responses.

Adjacent digits in the forties and fifties give a broad peak near fifty,
including inside larger numbers. The response is weaker inside digit runs
and across decimal punctuation. A separate negative response marks d/D
labels followed by a period or closing parenthesis, strongest at line
beginnings. Continued word pieces after d get a small positive baseline.
"""
READS = ()


def digit(s):
    return len(s) == 1 and '0' <= s <= '9'


def number_response(tens, ones):
    n = int(ones)
    if tens == '4':
        return 0.93 * n - 0.054 * n * n
    return 3.4 + 0.36 * n - 1.23 * max(0, n - 3)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, blank, label_start = '', '', True, True
    else:
        _, previous, before, blank, label_start = carry

    value = 0.0
    if digit(token):
        if previous in ('4', '5'):
            # Most preceding digits damp the pair; a preceding 1 does not.
            scale = 0.55 if digit(before) and before != '1' else 1.0
            value = scale * number_response(previous, token)
        elif previous in ('.', ',') and before in ('4', '5'):
            scale = 0.45 if previous == '.' else 0.30
            value = 0.2 + scale * number_response(before, token)
    elif token in ('.', ')') and previous.strip().lstrip('(') in ('d', 'D'):
        if token == '.':
            value = -5.5 if label_start else (
                -2.3 if previous[:1].isspace() else -0.7
            )
        elif token == ')':
            parenthesized = '(' in previous or before.rstrip().endswith('(')
            if label_start:
                value = -5.5 if parenthesized else -7.4
            else:
                value = -0.5 if parenthesized else -2.7
    elif previous in ('4', '5') and token in ('.', ')'):
        value = -0.35 if token == '.' else -0.2
    elif previous.lower().endswith('d') and token[:1].isalpha():
        value = 0.18

    # Keep track of a line's initial whitespace and optional opening '('.
    was_blank = blank
    if '\n' in token:
        blank = not token.rsplit('\n', 1)[1].strip(' \t\r(')
    elif token.strip(' \t\r('):
        blank = False
    return (doc, token, previous, blank, was_blank), value

"""A sparse mixture of orthographic triggers.

Right-angle separators, selected Greek consonants, and an initial
'Title:' colon are positive. Hungarian sz and several Hungarian consonant
and possessive-suffix fragments are negative, as are paired middle dots.
Script and recent word frequencies distinguish running text from formulas
or other languages. Unrecognized tokens give zero; this is only an
approximation, not a single semantic detector. Smaller rules cover thorn,
Arabic shadda and ظ, and the split-byte completion of Gurmukhi bha.
"""
import regex as re
from wordfreq import zipf_frequency

READS = ()


def hungarian(text):
    if any(c in text for c in 'őűŐŰ'):
        return True
    words = re.findall(r'[^\W\d_]{2,}', text.lower())[-8:]
    score = 0.0
    for word in words:
        other = max(zipf_frequency(word, lang)
                    for lang in ('en', 'de', 'pl', 'nl', 'cs', 'tr'))
        score += zipf_frequency(word, 'hu') - other
    return bool(words) and score > len(words) * 0.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, b'', b'', 0)
    _, position, recent, previous, angles = carry
    raw = prefix.token_bytes[-1]
    token = raw.decode('utf-8', 'replace')
    s = token.strip()
    before = recent.decode('utf-8', 'ignore')
    joined = (recent + raw).decode('utf-8', 'ignore')
    value = 0.0
    greek = bool(re.search(r'\p{Script=Greek}{4,}', before[-100:]))

    if s == '··':
        value = -1.66
    elif token in ('>>', ' >>'):
        if token.startswith(' '):
            value = 2.0 + 2.0 / (1.0 + 0.25 * angles)
        elif '<' in before[-60:] and not before.endswith(('\n', 'cin')):
            value = -0.2  # Closing nested generic types, not a separator.
        elif 'cin' in before[-60:]:
            value = 1.7
        else:
            value = 4.2 if before.endswith('\n') else 2.5
        angles += 1
    elif s == '<<':
        value = 0.15
    elif position == 1 and previous == b'Title' and s == ':':
        value = 5.44
    elif s.lower().startswith('sz'):
        if hungarian(before) or position == 0:
            value = -4.0 if s.lower() == 'sz' else -1.8
            if before.endswith('í'):
                value = -1.8
        else:
            value = -0.2
    elif token == 'z' and before.endswith('s'):
        value = -3.1 if hungarian(before) else -0.8
    elif token in ('zn', 'zer', 'ja', 'je', 'gg') and hungarian(before):
        value = {'zn': -3.1, 'zer': -2.1, 'ja': -1.8,
                 'je': -2.3, 'gg': -1.8}[token]
    elif s == 'ő' and before.endswith((' ', '\n')):
        value = 3.3
    elif raw == b' \xcf':  # A token ending halfway through a Greek letter.
        value = 1.1 if greek else 0.0
    elif joined and joined[-1] in 'ψθξφζΘ' and len(raw) <= 3:
        letter = joined[-1]
        split = 0x80 <= raw[0] < 0xC0
        if letter == 'ψ':
            if greek:
                value = 5.2 if split else 4.7
            else:
                value = 0.8 if split else 0.35
        elif split:
            initial = {'θ': 2.5, 'Θ': 3.8, 'ξ': 1.8, 'φ': 0.0, 'ζ': 1.2}
            value = initial[letter] if greek else 0.05
        elif letter == 'φ':
            if token.startswith(' ') and greek:
                value = 1.2
            elif before.endswith('σ'):
                value = -0.5
    elif s == 'psi':
        value = 0.4
    elif s == 'þ':
        value = 0.1 if re.search(r'\b\w\s*$', before) else 1.5
    elif s == 'ّ':  # Shadda following the Arabic semivowels is strongest.
        value = 2.2 if before.endswith(('و', 'ي')) else 0.4
    elif s == 'ظ':
        value = 4.5 if before.endswith('و') else 1.5
    elif raw == b'\xb8' and joined.endswith('ظ'):
        value = 5.5
    elif raw == b'\xad' and joined.endswith('ਭ'):
        value = 3.0  # Completion of Gurmukhi bha.

    return (doc, position + 1, (recent + raw)[-256:], raw, angles), value

"""A first-token pulse, modulated by the token's written form.

At the first visible token of a row or document, lowercase words and
fragments, non-Latin text, headings, and indentation give positive pulses. Digits and sentence-initial
capitalized words are weaker or negative. English word frequency separates
familiar words from unusual fragments. Elsewhere the prediction is zero except
for include-file quotes and doubled backslashes: positive in mathematical
notation, negative in escaped strings. These are group averages, not a token
lookup; idiosyncratic first-token amplitudes remain unexplained.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
MATH = re.compile(
    r'\\(?:begin|end|frac|left|right|text|quad|sum|int|partial|sigma)'
    r'|[_^]\{|\$\$'
)
IMPORT_WORDS = {'package', 'import', 'using', 'require', 'from'}


@lru_cache(maxsize=8192)
def first_value(text):
    word = text.strip()
    if word == '<|im_start|>':
        return 1.43
    if word == '<|endoftext|>':
        return 4.49
    if word == '<|im_end|>':
        return 0.83
    if word.isdigit():
        return -0.68 if word.isdecimal() else 2.5
    if text.isspace():
        if '\n' in text or '\r' in text:
            return -0.25
        return -0.1 if len(text) == 1 else 0.8 if len(text) == 2 else 2.6
    if word.startswith('\\'):
        return -1.4
    letters = ''.join(c for c in word if c.isalpha())
    if letters:
        if any('LATIN' not in unicodedata.name(c, '') for c in letters):
            return 1.4
        spaced = text.startswith(' ')
        freq = zipf_frequency(word.lower(), 'en')
        if word.islower():
            if word in IMPORT_WORDS and not spaced:
                return 2.8
            if not word.isalpha():
                return 1.6
            if spaced:
                return 0.78 if freq >= 6 else 1.1 if freq >= 5 else 1.65
            return 0.9 if freq >= 6 else 1.9
        if word.isupper():
            return (1.0 if spaced else 0.3) + (0.9 if freq < 3 else 0)
        if word.istitle():
            return (0.5 if spaced else 0.0) + (
                -0.6 if freq >= 6 else -0.2 if freq >= 5 else 0.25
            )
        return 2.4  # mixed-case identifiers
    if word and all(c == '#' for c in word):
        return 3.0
    if '\n' in text:
        return -0.35
