    ("escape", "("): 1.3, ("escape", "none"): 0.9, ("escape", "{"): 1.0, ("escape", "["): 1.5,
    ("paren", "("): 0.8, ("paren", "{"): 0.8, ("paren", "none"): 0.7, ("paren", "["): 0.4,
    ("space", "("): 0.9, ("space", "{"): 0.6, ("space", "none"): 0.08, ("space", "["): 0.8,
    ("other", "("): 0.5, ("other", "{"): 0.0, ("other", "none"): 0.1, ("other", "["): 0.1,
}


def split_lead(token):
    """Split a token into its leading opener characters and the rest."""
    i = 0
    while i < len(token) and token[i] in OPENERS:
        i += 1
