    toks = prefix.token_strings
    new_doc = len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    stack = "" if new_doc or carry is None else carry  # open brackets, innermost last
    cur = toks[-1]
    prev = "" if new_doc else toks[-2].strip()
    lead, core = split_lead(cur)
    value = 0.0

    if prev == "<<" and core in ('"', "'") and not lead.strip().isalpha():
        value = 3.0 if core == "'" else 1.0  # heredoc opener
    elif (len(toks) > 2 and not new_doc and prev in ("'", '"') and cur.isupper()
          and toks[-2].strip() == "'" and toks[-3].strip() == "<<"):
        value = 10.0  # heredoc delimiter word, e.g. EOF
    elif lead and core in ('"', '\\"', "'", "`"):
        bracket = stack[-1] if stack else "none"
        if "\\" in lead:
            kind = "escape"
        elif "(" in lead:
            kind = "paren"
        elif lead[-1] in " \t\n":
