# Short, conventional constructions beginning with 'as'.
AS_PHRASES = {
    'far': 4.6,
    'long': 1.6,
    'per': 4.0,
    'ever': 4.6,
    'for': 3.8,
    'of': 1.1,
    'any': 0.9,
    'only': 3.2,
    'best': 3.1,
    'close': 1.9,
    'always': 1.8,
    'part': -3.8,
    'being': -4.9,
    'compared': -4.2,
    'needed': -4.0,
    'appropriate': -3.7,
    'necessary': -3.1,
    'applicable': -3.6,
    'applied': -2.8,
    'opposed': -2.2,
    'such': -1.4,
    'possible': -0.45,
    'required': -0.7,
    'amended': -1.3,
    'shown': -0.3,
}
COMPARISON_ENDINGS = {'well', 'far', 'long', 'much', 'many', 'soon', 'such'}


@lru_cache(maxsize=4096)
def can_be_graded(word):
    return bool(wordnet.parts_of_speech(word) & {'adjective', 'adverb'})


def response(t, context):
    w = t.strip()
    low = w.lower()
