    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        carry = None
    before = "" if (carry is None or tok[:1].isspace()) else carry
    new_carry = "" if any(c.isspace() for c in tok) else (before + tok)[-60:]
    name = tok.lstrip("/.\\").lower()
    if tok in SPECIAL:
        return new_carry, SPECIAL[tok]
    if tok[:1] in (".", "\\") or before[-1:] in (".", "\\"):
        return new_carry, float(PACKAGE.get(name, 0.0))
    if tok[:1] == "/" or "/" in before:
        return new_carry, float(PATH_FOLDER.get(name, 0.0))
    if tok[:1] == " " and tok[1:].lower() in SPACE_FOLDER:
        return new_carry, float(SPACE_FOLDER[tok[1:].lower()])
    if not before and name in BARE_START:
        return new_carry, float(BARE_START[name])
    return new_carry, 0.0

"""Layer 1, MLP down-projection, component 1199: a document-start detector.

The component is almost silent inside a document. It fires on the first token of each
document (position 0 of a packed row, or the first token after a document break), and how
strongly it fires there depends on what kind of token that is:

- words about exchanging messages and data (receive, response, request, send, reply, post,
  file, packet, signal, session, server, client, ...): strongly positive, about 10;
- ordinary content words: a little positive, about 2.7;
- other symbols, code and non-Latin tokens: about 1.8;
- punctuation and whitespace: about 1;
- function words and pronouns (the, of, he, ...), digits, and single capital letters: near 0;
- chat-template markers such as <|im_start|>: about 3.

Everywhere else the program predicts 0. The levels are the average activation per class
over document-start tokens, weighted by how often each token starts a document.
"""

import re
from collections.abc import Mapping

READS = ()

FUNCTION_WORDS = frozenset(
    """the a an and or but of to in on at by for with from as is are was were be been it its
    this that these those he she we you they i me him her us them my your his our their not no
    can will would should could do does did if then than so such there here what which who when
    where how all any each some more most one just also into over about up out""".split()
)
EXCHANGE_WORDS = frozenset(
    """receive received receiver receiving receives response responses respond responded reply
    replies answer request requests post posts send sent sender file files page mail email
    message messages signal signals packet packets session sessions connect connection serve
    server client socket network fetch submit offer data user users input output""".split()
)
LEVELS = {
    "exchange": 10.5,
    "content": 2.7,
    "symbol": 1.8,
    "punct": 1.1,
    "space": 1.5,
    "function": 0.4,
    "digit": 0.3,
    "single_upper": 0.2,
    "single_lower": 0.6,
    "special": 2.9,
}


def kind(token: str) -> str:
    if token.startswith("<|"):
        return "special"
    word = token.strip()
    if not word:
        return "space"
    if re.fullmatch(r"[A-Z]", word):
        return "single_upper"
    if re.fullmatch(r"[a-z]", word):
        return "single_lower"
    if not any(c.isalnum() for c in word):
        return "punct"
    if re.fullmatch(r"\d+", word):
        return "digit"
    if not re.fullmatch(r"[A-Za-z]+", word):
        return "symbol"
    lower = word.lower()
    if lower in FUNCTION_WORDS:
        return "function"
    if lower in EXCHANGE_WORDS or any(k in lower for k in ("recei", "respon", "request", "recv")):
        return "exchange"
    return "content"


def step(carry, prefix, upstream: Mapping):
    position = prefix.position
    starts_document = position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return carry, 0.0
    return carry, LEVELS[kind(prefix.token_strings[-1])]

programs.sol:
"""A coarse document-onset pulse with local continuation corrections.

At document starts, broad spelling and spacing classes set a positive pulse;
chat delimiters and code fences are treated separately. Later predictions
are small. Commas and English clause-linking words lean negative, especially
around numerical annotations; words after articles and dotted names lean
positive. A few early-document and early-line corrections model fragments.

These rules omit individual-token offsets and do not reliably locate the
rare, very large negative spikes following layout breaks.
"""
import re

READS = ()
ARTICLES = frozenset(('a', 'an', 'the'))
RELATIVES = frozenset(
    ('which', 'that', 'who', 'whom', 'whose', 'where', 'when')
)
CONJUNCTIONS = frozenset(
    'and or but nor yet so because although while if unless until '
    'since whether'.split()
)
AUXILIARIES = frozenset(
    'is are was were be been being am can could will would shall should '
    'may might must do does did have has had'.split()
)


def first_token(s):
    word = s.strip()
    if s == '<|im_start|>':
        return 0.137
    if s == '<|endoftext|>':
        return -0.570
    if word.startswith('```'):
        return -0.716
    if word.isascii() and word.isalpha():
        if s.startswith(' '):
            return 0.629
        if len(word) <= 3:
            return 0.522
        if len(word) == 4:
            return 0.416
        return 0.471 if word.islower() else 0.289
    if s.startswith(' '):
        return 0.426
    punctuation = bool(word) and not any(c.isalnum() for c in word)
    return 0.370 if punctuation else 0.265


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    word = s.strip()
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', (), 0, False)
    _, position, previous, digits, line_position, lower_line = carry
    w = word.lower()
    prev = previous.strip()
    close = bool(re.search(r'[)\]}][,.;]*$', prev))
    numeric_context = sum(digits) >= 2
    value = 0.002
    if word.endswith(',') and not any(c in word for c in '\'"“”'):
        value = -0.014
        if lower_line and line_position == 2:
            value = -0.128
    elif prev.lower() in ARTICLES:
        value = 0.010
    elif re.match(r'\.[a-zA-Z]', word):
        value = 0.020
    elif numeric_context and w in RELATIVES:
        value = (
            -0.020 if prev.isascii() and prev.isalpha() else -0.073
        )
    elif numeric_context and w in CONJUNCTIONS and close:
        value = -0.102
    elif numeric_context and w in ARTICLES:
        value = -0.018
    elif len(word) == 2 and w in AUXILIARIES:
        value = -0.014
    if 0 < position < 5:
        if re.search(r'[.!?][\s"\')\]]*$', s):
            value -= 0.080
        elif w in RELATIVES or w in CONJUNCTIONS:
            value -= 0.045
    if position == 0:
        value = first_token(s)
    if '\n' in s:
        line_position, lower_line = 0, False
    else:
        if line_position == 0 and word:
            lower_line = word[0].islower()
        line_position += 1
    carry = (doc, position + 1, s, (digits + (word.isdecimal(),))[-16:],
             line_position, lower_line)
    return carry, value

"""Approximate a spelling-sensitive s-cluster response.

Short g/j continuations after s-like endings are positive; w/v are negative.
Attenuate long-word and CamelCase junctions and internal g in -ng or before
vowels. Recognize short sg/sw pieces, several sw word families and acronym
separators. Fold Latin accents and Cyrillic spelling; retain a decaying echo
only while letters continue, resetting at document boundaries.

Repeated middle dots and a row-initial end-of-text marker are separate
positive responses. Amplitudes are conservatively scaled by 0.82.
"""
import math
import regex as re
from anyascii import anyascii
import unicodedata
from functools import lru_cache

READS = ()


@lru_cache(maxsize=8192)
def normalize(text):
    if re.search(r'\p{Script=Cyrillic}', text):
        text = anyascii(text)
    return ''.join(c for c in unicodedata.normalize('NFKD', text.lower())
                   if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, previous, echo = carry
    raw = prefix.token_strings[-1]
    text = normalize(raw)
    word = text.lstrip(' _/-')
    continuing = bool(text) and text[0].isalpha()
    strength = 0.0
    if continuing:
        if previous.endswith('s'):
            strength = 1.0
        elif previous.endswith(('sh', 'sch')):
            strength = 0.8
        elif previous.endswith('sz'):
            strength = 0.8
        elif re.search(r's[aeiou]$', previous):
            strength = 0.3
    value = 0.0
    if strength:
        # A capitalized word after a lowercase word is usually CamelCase,
        # rather than a continuation of the same spelling.
        if raw[0].isupper() and len(raw) > 2:
            strength = 0.0
        if len(previous.strip()) > 4 and len(text) > 1:
            strength *= 0.3
        if text in ('g', 'j', 'w', 'v'):
            value = {'g': 5.2, 'j': 3.6, 'w': -5.8, 'v': -2.7}[text]
        elif text.startswith(('w', 'v')):
            value = -2.8 / max(1, len(text) - 1)
            if re.match(r'w(?:ell|ing|ay|ick|ard|er)', text):
                value = -5.0
            elif (text in ('war', 'wara', 'var', 'vara')
                  and previous.endswith(('s', 'sh'))):
                value = -7.5
            elif text.startswith('v') and len(text) <= 3:
                value = -2.8
        elif text.startswith(('g', 'j')):
            value = 2.4 / max(1, len(text) - 1)
        elif 'g' in text[:6] and 'ng' not in text:
            at = text.index('g')
            value = 5.0 * math.exp(-0.4 * at)
            if at + 1 < len(text) and text[at + 1] in 'aeiouyg':
                value *= 0.05
            if text.startswith('i'):
                value *= 0.25
            elif text[0] in 'aeu' and raw[0] in 'aeuAEU':
                value *= 0.1
        value *= strength
    if previous.strip(' .\t') == 's' and raw == '.W':
        value = -5.0
    if word == 'sg':
        value = 4.3 if text == word else 1.4
    elif word.startswith('sg'):
        value = 1.1
    if previous.strip() == 's' and raw in (' W', ' G'):
        value = -6.0 if raw == ' W' else 1.0
    if word == 'sw':
        value = -3.3
        if raw.strip() == 'Sw':
            value = -2.6
        elif raw.strip() == 'SW':
            value = -2.0 if raw.startswith(' ') else -4.0
    elif word.startswith(
            ('sway', 'swell', 'swing', 'swear', 'swip', 'swarm')):
        value = -3.7
        if word.startswith('sway'):
            value = -5.5
    elif word == 'swan':
        value = -3.4
    elif word.startswith(('swagger', 'swer')):
        value = -1.8
    elif word.startswith(('swoll', 'swung')):
        value = -2.3
    if continuing:
        decay = 0.6 if previous.strip(' _/-') == 'sw' else 0.3
        value += decay * echo
    if word == 'sv':
        value = -0.7 if 'с' in raw.lower() else -1.7
    if len(text) > 1 and set(text) == {'·'}:
        value = 1.1
    if prefix.position == 0 and raw == '<|endoftext|>':
        value = 4.0
    return (doc, text, value), 0.82 * float(value)

"""A local signed spelling filter, approximating part of this component.

Read the letters just after a Z-like letter, either in this token or across
one token boundary. OL/OR, A with early L/R, and isolated L/R are negative.
W-containing fragments without early L/R are usually positive; common whole
words suppress that response. Short-piece rules provide weaker estimates.
Transliteration shares these rules across scripts. Separate negative rules
cover Chinese 扎, Thai จั, and the colon of a document-opening 'Title:' field.
No other context or semantic behavior is modeled.
"""
from functools import lru_cache
import unicodedata
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
Z_LETTERS = frozenset('zZзЗжЖζΖزذظז')
LANGUAGES = ('en', 'de', 'ru', 'pl', 'cs', 'hu', 'tr', 'nl', 'es', 'pt')

@lru_cache(maxsize=32768)
def z_parts(text):
    for i in range(len(text) - 1, -1, -1):
        base = unicodedata.normalize('NFD', text[i])[0]
        if base in Z_LETTERS:
            return text[:i].strip(), text[i + 1:]
    return None

@lru_cache(maxsize=32768)
def response(fragment, inside, token, before):
    q = anyascii(fragment).lower()
    if not q or not q.isalpha():
        return 0.0
    liquid = any(c in 'lr' for c in q[:3])
    if liquid:
        if q.startswith(('ol', 'or')):
            return -4.2
        if q[0] == 'a':
            if not inside:
                return -2.0
            return -1.2 if not before else -0.18
        if len(q) == 1:
            return -1.05 if inside else -2.1
        return 0.0 if inside else -0.33
    if 'w' in q[:3]:
        if inside:
            frequency = max(zipf_frequency(token.strip().lower(), lang)
                            for lang in LANGUAGES)
            if frequency > 4.0:
                return 0.0
        if 'a' in q[:3]:
            return 2.8
        return 1.95 if q[0] == 'w' else 0.24
    if inside:
        if len(q) == 1:
            return -0.4 if q == 'o' else 0.0
        return 0.11 if not before else 0.0
    if len(q) > 1 and q[1] in 'dt':
        return 1.26 if len(before) <= 1 else 0.32
    return 0.8 if q[0] == 'u' else 0.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is not None and carry[0] == doc:
        previous, position = carry[1], carry[2] + 1
    else:
        previous, position = '', 0
    token = prefix.token_strings[-1]
    value = 0.0
    current = z_parts(token)
    if current is not None and current[1] and current[1].isalpha():
        value = response(current[1], True, token, current[0])
    elif not token[:1].isspace():
        old = z_parts(previous)
        if old is not None and len(old[1]) <= 1:
            value = response(old[1] + token, False, token, old[0])
    if token.strip() == '扎':
        value = -3.0
    if previous.endswith('จ') and token.startswith('ั'):
        value = -1.2 if token.startswith('ัด') else -3.5
    if position == 1 and previous == 'Title' and token == ':':
        value = -3.79
    return (doc, token, position), value

"""Opening Hydro-, a few document headers, and literal token-format cues.

A large positive pulse marks the second token of document-initial ``Hydro``.
It does not mark chemistry words generally. Smaller rules cover initial
Python/role-label tokens, structured-data/archive suffixes, and middle-dot
leaders. Unmodelled activity is approximated by a small constant.
"""
READS = ()

DATA_SUFFIXES = {'.json', '.yaml', '.yml', '.xml', '.toml'}
ARCHIVE_SUFFIXES = {'.zip', '.gz', '.tar', '.rar', '.7z', '.jar', '.bz', '.xz'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        n, opening, previous = 0, '', ''
    else:
        _, n, opening, previous = carry
    opening = opening + token if n < 2 else ''

    value = 0.003
    if token in DATA_SUFFIXES:
        value = 0.22
    elif token in ARCHIVE_SUFFIXES:
        value = 0.17
    if n == 0:
        if token == 'Hy':
            value = 0.122
        elif token == 'def':  # Python function-definition keyword
            value = -1.31
        elif token in {'assistant', 'user'}:
            value = 0.45
    if token == '··' and (n == 0 or previous == token):
        value = -0.67
    if n == 1 and opening == 'Hydro':
        value = 1.95
    return (doc, n + 1, opening, token), value

"""Symbolic separators rather than ordinary spaced prose.

Predict positive contributions for attached operators, identifier/path separators,
and compact lists. Whitespace usually suppresses them. Small contextual rules
distinguish comparisons from closing tags and percent signs from remainder
operators. A few English date spaces and Java's 'package com' prefix have
separate positive strengths.
All strengths are approximate; ordinary text is assigned zero.
"""
import re
import unicodedata

READS = ()
SIGNS = {
    '=': 1.8, '+': 1.5, '*': 1.0, '/': 0.85, '-': 1.0,
    '–': 2.0, '—': 0.9, '‐': 0.9, '−': 0.9,
    '<': 1.6, '>': 1.5, '^': 1.05, '×': 1.3, '÷': 1.4,
    '&': 0.9, '|': 0.65, '~': 1.1, '≠': 1.3, '≈': 1.3,
    '·': 1.1, '√': 0.7,
}
SEPARATORS = {
    '_': 0.58, '__': 1.25, '::': 0.95, '://': 1.5,
    '->': 1.45, '=>': 1.3, '&&': 0.9, '||': 0.95,
    '>&': 1.05, '··': 0.5, '…': 0.8, '・': 0.77,
}
MONTHS = (
    r'(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|'
    r'June?|July?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|'
    r'Nov(?:ember)?|Dec(?:ember)?)'
)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    before = tail[-1:]
    attached = bool(before and not before.isspace())
    word_match = re.search(r'[^\W\d_]+\Z', tail)
    word = word_match[0] if word_match else ''
    number = bool(before and before.isdigit())
    value = 0.0

    if s in SIGNS and attached:
        value = SIGNS[s]
        if s == '-':
            value = 1.06 if number else 0.4
            if word:
                value = 1.25 if len(word) == 1 else 0.55
                if word.isupper():
                    value = 1.0
                if any('CYRILLIC' in unicodedata.name(c, '') for c in word):
                    value = 1.25
        elif s == '=':
            value = 1.35 if number else 1.9 if word else 1.0
        elif s == '+':
            value = 1.4 if number else 1.6 if len(word) == 1 else 1.0
            if before == '^':
                value = 0.0
        elif s == '*':
            value = 1.7 if number else 0.65
        elif s == '/':
            value = 0.95 if number else 1.3 if len(word) == 1 else 0.7
            if word and word.isupper():
                value = 1.4
            if re.search(r'\.(?:com|org|net|edu|gov)\Z', tail):
                value = 0.1
        elif s == '<':
            value = 2.2 if len(word) == 1 else 1.5 if word else 0.1
        elif s == '>':
            angle = tail[tail.rfind('<'):] if '<' in tail else ''
            if angle and '>' not in angle:
                value = -0.8 if re.match(r'</|<[A-Z]', angle) else 0.4
            else:
                value = 2.2 if len(word) == 1 else 0.3
        elif s in ('–', '—') and not (word or number):
            value = 0.1
    elif s == '*' and before.isspace():
        value = 0.3
    elif s in SEPARATORS:
        value = SEPARATORS[s]
        if s in ('->', '=>') and not attached:
            value = 0.1
    elif re.fullmatch(r'[)\]}]+[+*/=<>–—-]|[\"\']\+', s):
        value = {'+': 1.85, '*': 2.0, '/': 1.3, '=': 1.6,
                 '<': 1.5, '>': 1.5, '-': 1.4, '–': 2.0,
                 '—': 1.6}[s[-1]]
    elif s in ('==', '!=', '<=', '>=', '<<', '|='):
        value = 1.8 if attached else 0.1
    elif s in ('**', '``', '...', '..', '--', '---'):
        value = 2.0 if s == '..' and number else 0.5
        if s in ('--', '---'):
            value = 0.95 if word or number else 0.1
        elif s == '**':
            value = 0.2
    elif re.fullmatch(r'__+/', s):
        value = 1.25
    elif s in ('(', '[', '{'):
        value = {'(': 0.43, '[': 0.75, '{': 0.2}[s] if attached else 0.05
        if s == '{' and tail.endswith('\\end'):
            value = 1.7
    elif s == ' {':
        value = 0.5
    elif s != '](' and re.fullmatch(r'[)\]},]+[({\[]', s):
        value = 0.7
    elif re.fullmatch(r'(?:\(\))?[)\]}]*\{\r?\n', s):
        value = 1.4 if s.rstrip() != '{' else 1.0 if attached else 0.1
    elif s in ('*(', '=(', '={', '=-', '!(', '^{', '_{'):
        value = 0.65 if s != '_{' else 0.33
    elif re.fullmatch(r'[)\]}]+\^', s):
        value = 0.9
    elif s == ',':
        if before == '\\':  # TeX's explicit thin space
            value = 1.7
        elif re.search(r',[^,\s]{1,40}\Z', tail):
            value = 0.95
    elif s == '%':
        value = 2.2 if word and attached else 0.2 if number else 0.0
    elif s == '@':
        value = 1.7 if re.search(r'[\w.+-]{2,}\Z', tail) else 0.1
    elif s == '\\':
        value = 1.3 if len(word) > 1 and word[0].isupper() else 0.0
    elif s == '\\\\':
        value = 1.9 if '&' in tail or '\\begin{' in tail else 0.5
    elif s == 'x' and number:
        value = 0.8
    elif s in ('times', 'cdot') and before == '\\':
        value = 1.3
    elif s == '.com':
        value = 0.44
    elif s == ' com' and tail.endswith('package'):
        value = 5.0  # beginning a reverse-domain Java package name
    elif s == '\xa0' and before in ('–', '—'):
        value = 1.2
    elif s == ' ':
        date = (r'\d{1,2} ' + MONTHS + r'\Z|' + MONTHS
                + r' \d{1,2}(?:st|nd|rd|th)?,?\Z')
        if re.search(date, tail):
            value = 1.1
    return (doc, (tail + s)[-100:]), value

"""Approximate local AD-spelling response, not a general semantic classifier.

Recognize 'ad' pieces and a/d split across pieces, also in transliteration
(excluding Han). Strength depends on piece length, capitalization, and the
immediate continuation. Admin, phpMyAdmin, Active Directory and katakana ado
have stronger responses. Document starts and repeated middle dots are negative.
Magnitudes were fitted on training text; lexical/contextual variation remains.
"""
from functools import lru_cache
import regex
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=8192)
def spelling(raw):
    if regex.search(r'\p{Script=Han}', raw):
        return ''
    # Preserve Arabic alef, which the transliterator otherwise omits.
    text = anyascii(raw.replace('ا', 'a'))
    return ''.join(c for c in text if c.isalpha())


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, old_capital = ('', None) if first else carry[1:]
    letters = spelling(raw)
    s = letters.lower()
    before = spelling(previous)
    p = before.lower()
    continuation = bool(letters) and not raw[:1].isspace()
    capital = (old_capital if continuation and old_capital is not None
               else letters[:1].isupper())
    value = -0.29 if first else 0.0

    if 'ad' in s:
        if s == 'admin':
            value += 3.0 if raw[:1].isspace() else 3.8
            if p == 'my' and continuation:  # phpMyAdmin
                value += 7.3
        elif s == 'ad':
            value += 1.13
        elif 'add' in s:
            value += 0.19
        else:
            value += 0.12
            if len(s) <= 6 and s.startswith('ad'):
                value += 0.43
        if capital and len(s) <= 6:
            value += 0.19

    if continuation and before:
        if p.endswith('a') and s.startswith('d'):
            value += 0.49
            if p == 'a':
                value += 1.86
            if before == 'A':
                value += 1.41
            if p == 'a' and s == 'do' and regex.search(
                    r'\p{Script=Katakana}', raw):
                value += 5.14
        elif 'ad' in p and len(p) <= 5:
            value -= 0.17
            if s[:1] in 'aeiouy':
                value += 0.16
            if len(s) <= 2:
                value += 0.47
            if p.endswith('ad'):
                value += 0.33
            if p == 'ad':
                value += 0.55

    if previous.strip().lower() == 'active' and raw.strip().lower() == 'directory':
        value = 5.27
    if len(raw) >= 2 and all(c == '·' for c in raw):
        value = -1.44

    next_capital = capital if raw[-1:].isalpha() else None
    return (doc, raw, next_capital), float(value)

"""Respond to boundaries in imports and qualified names, rather than prose.

Python's `from module import` has the largest negative response. Named
JavaScript imports, Rust `use` paths, PHP namespaces, C header extensions,
and the end of Java/C# imports have smaller negative responses. Type-body
openings, macro definitions, path slashes and aliases also contribute.
Direct `import` is positive, especially at a document start. Most other
positions are near zero. A 600-character text tail supplies context and
is reset at document boundaries.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    before = history.replace('\\n', '\n').replace('\\r', '\r')
    line = before.rsplit('\n', 1)[-1]
    value = 0.2 if not history else 0.0
    if token.strip() == 'import':
        match = re.search(r'\bfrom\s+([\w.]+)\s*$', line)
        if match and match[1] not in ('an', 'the', 'another'):
            module = match[1]
            if module in ('typing', 'typing_extensions'):
                value = -7.5
            elif module == 'collections':
                value = -9.5
            else:
                value = -15.0
        else:
            value = 4.0 if not history and token == 'import' else 0.4
    elif token == ' as':
        if re.search(r'\bimport\s+[\w.]+$', line):
            module = line.split('import')[-1]
            value = -8.0 if '_' in module else (-7.0 if '.' in module else -5.0)
        elif re.search(r'\bexcept\s+[\w.]+$', line):
            value = -2.5
    elif token == ' from':
        if re.search(r'\bimport\s+(?:type\s+)?(?:\w+\s*,\s*)?'
                     r'(?:\{[\w\s,]+}|\w+)\s*$', line):
            value = -2.4
        elif re.search(r'\bimport\s+\*\s+as\s+\w+$', line):
            value = -1.0
    elif token.lstrip().startswith('{') and re.search(
            r'\bimport(?:\s+type|\s+\w+,)?\s*$', line):
        value = -3.7
    elif token.startswith('::'):
        value = -1.7
        match = re.search(r'\buse\s+([\w:]+)$', line)
        if match:
            root = match[1].split('::')[0]
            if root in ('self', 'super') or root[0].isupper():
                value = -3.0
            else:
                value = -13.0 if '{' in token else (-3.5 if '*' in token else -7.5)
        elif re.search(r'\btest\s+(?:src/|[\w:]+$)', line):
            value = -3.0
        elif '.py' in line or 'PASSED' in before[-150:]:
            value = -1.0
    elif token.startswith('\\') and re.fullmatch(r'\\+[A-Za-z]*', token):
        if re.search(r'\b(use|namespace)\s+[\w\\]+$', line):
            value = -4.0 if len(token.lstrip('\\')) <= 1 else -2.0
    elif token in ('.h', '.hpp', '.hh', '.hxx'):
        value = -4.3 if '#include' in line else -0.2
    elif token.lstrip().startswith('(') and re.search(
            r'\bimport(?:\s+[\w.]+)?\s*$', line):
        value = -2.8
    elif token.startswith(';') or token.startswith('.*;'):
        if re.search(r'\b(import|package|use|using)\s+[\w.*:]+$', line):
            value = -2.0 if '\n\n' not in token else -1.7
    elif token.startswith('"') and token.strip('"\r\n\\') == '':
        if re.search(r'"[\w./-]+$', line):
            value = -0.45
    elif token in ('/', '/\n', '/v'):
        path = re.search(r'[\w./-]+$', line)
        if re.search(r'://\S+$', line):
            value = -0.1
        elif '#include' in line:
            value = -3.0
        elif path and '/' in path[0]:
            value = -1.1 if token != '/v' else -0.65
        elif token == '/':
            value = -0.18
    elif token == '.v' and re.search(r'\b(import|package)\s+', line):
        value = -1.0
    elif token.startswith('.') and len(token) > 1 and token[1].isalpha():
        if re.search(r'\b(import|from|package)\s+', line):
            value = -0.8 if token[1].isupper() else 0.15
    elif token == '#define':
        value = -1.3
    elif '{' in token:
        declaration = line if line.strip() else before.rstrip().rsplit('\n', 1)[-1]
        if re.search(r'\b(class|struct|enum|interface|namespace|impl)\b'
                     r'[^;{}=]*$', declaration):
            value = -1.4
        else:
            value = -0.2
    return (doc, (history + token)[-600:]), value

"""Mostly a negative signal for 'sim' fragments and approximation signs.

Separated s + im receives a strong response; longer fragments dilute it.
Selected similarity and approximation words respond mildly. Spacing and capitalization modulate
the response. UTF-8 tails let a split mathematical sign count just once.
Two narrow punctuation responses are included: doubled middle dots, and a
bare // comment header at the start of a document. Other responses are omitted.
"""

READS = ()
LETTERS = str.maketrans({'с': 's', 'и': 'i', 'і': 'i', 'м': 'm'})
SIGNS = frozenset('~～〜∼≈≃≅∽')


def spelling(text):
    return text.lower().translate(LETTERS)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    tail, previous = (b'', '') if fresh else carry[1:]
    raw = prefix.token_bytes[-1]
    text = raw.decode('utf-8', 'replace')
    joined = (tail + raw).decode('utf-8', 'replace')
    current = spelling(text)
    prior = spelling(previous)
    word = current.strip()
    value = 0.0

    signs = [c for c in SIGNS if c in text]
    if not signs and '\ufffd' in text:
        signs = [c for c in SIGNS
                 if c in joined and raw.startswith(c.encode()[-1:])]
    if signs:
        sign = signs[0]
        if word == sign or '\ufffd' in text:
            value = -2.8
            if '\ufffd' in text:
                value = -6.8 if sign == '∼' else -3.9
            elif sign == '~':
                value = -3.4 if text.startswith(' ') else -1.8
                if '\n' in text:
                    value = -0.3
    elif text.strip().lower() == 'sim':
        value = -6.2
        if text.startswith(' '):
            value += 1.4
        if text.strip()[:1].isupper():
            value += 1.3
    elif prior.endswith('s') and current.startswith('im'):
        # A capitalized continuation usually starts a new name/identifier.
        if text[:1].isupper() and not text.isupper():
            value = 0.25
        else:
            value = -6.4 / (len(current) - 1) ** 1.5
    elif prior.endswith('s') and current.startswith('ym'):
        value = -1.4
    elif prior.strip() == 's' and current.startswith('ì'):
        value = -4.6
    elif word in ('similar', 'similarity'):
        value = -0.7 if word == 'similar' else -1.2
    elif word in ('simulation', 'simulations', 'simulator'):
        value = -0.5
    elif word in ('approx', 'approximately'):
        value = -1.1
        if text == 'approx':
            value = -2.7
    elif word == 'assim':
        value = -1.4
    elif word == 'im':
        value = 0.25
    elif word == '··':
        value = -1.37
    elif fresh and text == '//\n':
        value = -7.4

    return (doc, (tail + raw)[-2:], text), value
